window.__DCB_PREVIEW_DATA__["data/tariffs.json"] = "{\"generated_at\":\"2026-11-21\",\"tariffs\":[{\"id\":\"we-energies-very-large-customer-tariff\",\"utility\":\"We Energies (Wisconsin Electric Power Company)\",\"state\":\"WI\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Very Large Customer (VLC) tariff\",\"tariff_type\":\"Data center tariff\",\"status\":\"approved\",\"status_detail\":\"Wisconsin PSC approved, with modifications, April 24, 2026. Oracle (tenant/operator at the Stargate Lighthouse campus, see oracle-port-washington-wi) sued the PSC in Ozaukee County Circuit Court in June 2026 to overturn the credit-rating requirement below; the PSC declined to reconsider and will defend the rule in court (as of July 10, 2026) — see the credit-security additional term. The PSC's written order is dated May 21, 2026, and the tariff applies to service from June 1, 2026 (per the filed tariff sheet).\",\"regulator\":\"Public Service Commission of Wisconsin (PSCW)\",\"docket_number\":\"6630-TE-113\",\"decision_date\":\"2026-04-24\",\"min_load_mw\":100.0,\"customers\":[\"Microsoft\",\"Oracle\"],\"summary\":\"A special rate plan for data-center-scale customers in We Energies' territory; the PSC lowered the eligibility threshold from 500 MW to 100 MW and extended the minimum term to 15 years to prevent cost-shifting to existing customers (relevant to Microsoft's Mount Pleasant campus).\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Mandatory for new load with an aggregated customer forecast of 100 MW or more.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"customer aggregated load forecast of 100 MW or greater of new electric load\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Eligibility is measured on the customer's aggregated load forecast rather than a single site.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"customer aggregated load forecast of 100 MW or greater\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"VLC Service Agreement minimum term of 15 years with a one-year cancellation notice in year nine.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"VLC Service Agreement with a minimum term of fifteen (15)\"},\"min_billing_demand\":{\"status\":\"partial\",\"detail\":\"A Minimum Billed Demand Charge applies to transmission service when actual load-ratio-share demand falls below the minimum transmission demand.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"The Minimum Billed Demand Charge will be invoiced in billing periods when Customer\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Charges for transmission facilities built specifically for the customer are passed through to it.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"Any charges for the recovery of transmission facilities specifically built to serve Customer, will continue to be passed through to Customer\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Transmission facilities specifically built to serve the customer are charged to it as long as they are billed to the utility.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"Any charges for the recovery of transmission facilities specifically built to serve Customer, will continue to be passed through to Customer\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Customers subscribe to Bespoke Resources in MISO Zone 2 under a separate Bespoke Resources Tariff.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"in which customer subscribes to all or a portion of one or more Capacity-Only Bespoke Resources or Full-Benefit Bespoke Resources\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Customer subscribes to capacity-only or full-benefit resources that the utility procures; the PSC removed the capacity-only option in its order.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"in which customer subscribes to all or a portion of one or more Capacity-Only Bespoke Resources or Full-Benefit Bespoke Resources\"},\"load_flexibility\":{\"status\":\"included\",\"detail\":\"Market firm service volume is curtailed ahead of the utility's other firm retail customers in load shed; non-firm load is curtailed at MISO EEA2.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"be curtailed prior to firm service customers taking service under the Company\"},\"load_forecast_requirement\":{\"status\":\"included\",\"detail\":\"Customer files a 10-year load forecast each year.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"shall provide a 10-year load forecast no later than October 1\"},\"explicit_load_forecast\":{\"status\":\"included\",\"detail\":\"Forecast covers monthly peak demand and annual energy for near years and seasonal peaks out to year 11.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"Monthly peak demand and annual energy: June Year + 1 through May Year + 3\"},\"forecast_update_cadence\":{\"status\":\"included\",\"detail\":\"Forecast is due every October 1 for each year of the agreement.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"shall provide a 10-year load forecast no later than October 1\"},\"exit_fee\":{\"status\":\"partial\",\"detail\":\"On early termination the customer remains responsible for certain pass-through charges or receives credits; no fixed exit-fee formula is stated.\",\"source_url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"verbatim\":\"the customer shall continue to be responsible for\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"PSC states the Full-Benefits resource model protects existing customers by requiring very large customers to pay 100% of their costs.\",\"verbatim\":\"protects existing customers by requiring the VLCs to pay 100% of their costs.\"}},\"additional_terms\":[{\"term\":\"Credit-security requirement (litigated)\",\"detail\":\"The PSC's April 2026 order requires very-large-load customers to carry an A- (S&P) or A3 (Moody's) credit rating, or post equivalent financial security, and removed We Energies' ability to waive it. The PSC-approved rate structure would require Oracle's Port Washington subsidiary to provide more than $100M/year in cash deposits or letters of credit; Oracle sued to have the requirement set aside, and the PSC declined to reconsider and will defend it in Ozaukee County Circuit Court.\"}],\"legislation\":[],\"source_url\":\"https://psc.wi.gov/Documents/PressReleases/04.24.2026PressRelease.PDF\",\"source_title\":\"Wisconsin PSC — Press release on We Energies Very Large Customer tariff decision\",\"resources\":[{\"url\":\"https://www.we-energies.com/pdfs/etariffs/wisconsin/elecrateswi.pdf\",\"title\":\"We Energies — Wisconsin electric rate schedules\"},{\"url\":\"https://wisconsinwatch.org/2026/07/wisconsin-regulators-refuse-to-loosen-data-center-credit-rules-setting-up-oracle-court-fight/\",\"title\":\"Wisconsin Watch — Regulators refuse to loosen data center credit rules, setting up Oracle court fight\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"nj-large-load-tariff-2026\",\"utility\":\"All New Jersey electric public utilities (statewide framework)\",\"state\":\"NJ\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Data Center Fair Share Act (A796/S731) — Large Load Tariff Standards\",\"tariff_type\":\"Data center rate class / large-load rider\",\"status\":\"approved\",\"status_detail\":\"Passed both chambers of the NJ Legislature June 30, 2026 and signed into law by Governor Mikie Sherrill on July 7, 2026, as part of a broader energy-affordability package; directs the NJ Board of Public Utilities to establish the rate class by rulemaking. An earlier, differently-numbered version (A5462, 2024-2025 session) had passed the legislature but was pocket-vetoed by outgoing Governor Phil Murphy; it was reintroduced in the current session as A796/S731, which is what was actually signed. Some press coverage still refers to it by the original A5462 number.\",\"regulator\":\"New Jersey Board of Public Utilities (BPU)\",\"decision_date\":\"2026-07-07\",\"min_load_mw\":50.0,\"summary\":\"New Jersey's Data Center Fair Share Act creates a dedicated ratepayer class and rate structure for data centers with peak demand of 50 MW or more (lowered from an original 100 MW threshold), requiring them to pay for at least 85% of their contracted electric service for a minimum of 10 years so grid-infrastructure costs are not shifted to residential and small-business ratepayers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"partial\",\"detail\":\"Board sets a minimum MW size per utility by order within 12 months; the statute caps it at 50 MW.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"minimum megawatt size designation, which shall not be greater than 50 megawatts\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Board aggregates peak demand of data centers under common ownership or control, on the same or contiguous sites, and treats them as one.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"any data centers that are under common ownership or control, located on the same site or contiguous sites\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Customers must guarantee payment for 10 years from when service commences, or as the board's standards determine.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"it requests for a period of 10 years from when service commences\"},\"min_billing_demand\":{\"status\":\"partial\",\"detail\":\"Customers provide financial guarantees to pay for at least 85 percent of the electricity supply requested; billing mechanics are left to the board and utility tariffs.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"provides adequate financial guarantees that it will pay for at least 85 percent of the\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Utilities provide for deposits, financial security or (for high-rated customers) financial commitments sized to protect ratepayers over the 10-year period.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"provide for the posting of deposits, financial security\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Costs attributable to large data center customers are allocated to them, including generation, transmission, distribution and substation investments.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"the costs of any infrastructure investment related to generation, transmission, distribution, or substation facilities\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Generation investment incurred solely or primarily to serve the customer is allocated to it.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"the costs of any infrastructure investment related to generation, transmission, distribution, or substation facilities\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Transmission investment incurred solely or primarily to serve the customer is allocated to it.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"the costs of any infrastructure investment related to generation, transmission, distribution, or substation facilities\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Standards must incentivize customer-procured clean generation, storage and capacity resources and set how utilities assess them.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"incentivize large data center customers to bring their own\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Board standards incentivize customers to bring their own new clean generation or storage; customer-procured capacity reduces its share of backstop procurement costs.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"incentivize large data center customers to bring their own\"},\"btm_generation\":{\"status\":\"partial\",\"detail\":\"Board must develop a tariff framework for customers served in whole or part by co-located generation.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"develop a framework for the tariff treatment of large data center customers served in whole or in part by co-located generation\"},\"load_flexibility\":{\"status\":\"included\",\"detail\":\"Large data center customers are curtailed before residential customers in system emergencies (firm load shed), and a voluntary demand-reduction trade program is required.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"ensure the priority curtailment of large data center customers before residential customers\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Approved rates must reasonably protect other customers from transmission and distribution cost increases caused nearly entirely by large data center customers.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"reasonably protect other electric public utility customers against increased transmission and distribution costs\"},\"customer_type\":{\"status\":\"included\",\"detail\":\"Applies only to large data center customers, a class defined by board standards.\",\"source_url\":\"https://pub.njleg.state.nj.us/Bills/2026/S1000/731_R3.HTM\",\"verbatim\":\"means a data center that meets the size threshold and other defining characteristics established by the board\"}},\"additional_terms\":[{\"term\":\"Priority curtailment order\",\"detail\":\"During system emergencies, large data-center customers must be curtailed before residential customers — an explicit ratepayer-protection ordering rule not itself one of the 17 LBL elements.\",\"source_url\":\"https://www.utilitydive.com/news/new-jersey-lawmakers-send-data-center-tariff-bill-to-governor/824191/\"},{\"term\":\"Demand-reduction offset program\",\"detail\":\"Establishes a retail program outside the PJM capacity market letting large loads offset their capacity obligations by funding demand reduction elsewhere on the system — state officials described it as a first-of-its-kind mechanism.\"}],\"legislation\":[{\"policy_id\":\"nj-pl2026-c32\",\"title\":\"New Jersey A796/S731 (2026)\",\"url\":\"https://www.njleg.state.nj.us/bill-search/2026/S731\",\"citation\":\"A796/S731\",\"status\":\"Enacted 2026-07-07\",\"summary\":\"The enabling legislation — creates the data-center rate class directly and directs BPU implementation. (Note: an alternate njleg.gov bill-text URL found in an earlier draft of this record resolved to an unrelated homepage on direct verification and referenced a mismatched bill number in its own query string — dropped rather than kept unverified.)\"}],\"source_url\":\"https://www.nj.gov/governor/news/2026/20260707a.shtml\",\"source_title\":\"Office of Governor Sherrill — Ratepayer Relief energy legislation signing announcement\",\"resources\":[{\"url\":\"https://nj1015.com/nj-data-center-fair-share-law/\",\"title\":\"NJ 1015 — New Jersey becomes first state to put AI data centers in their own ratepayer class\"},{\"url\":\"https://www.assemblydems.com/m/newsflash/Home/Detail/13131\",\"title\":\"NJ Assembly Democrats — Bill to Protect Ratepayers from Data Center Energy Costs Signed Into Law (85%/10-year and 50 MW detail)\"},{\"url\":\"https://www.utilitydive.com/news/new-jersey-lawmakers-send-data-center-tariff-bill-to-governor/824191/\",\"title\":\"Utility Dive — New Jersey lawmakers send data center tariff bill to governor\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"aep-ohio-data-center-tariff\",\"utility\":\"AEP Ohio (Ohio Power Company)\",\"state\":\"OH\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Data Center Power Service / Mobile Data Center tariffs\",\"tariff_type\":\"Data center tariff\",\"status\":\"approved\",\"status_detail\":\"PUCO adopted the settlement July 9, 2025; compliance tariff effective July 23, 2025. Tariff sheets 223-1 to 223-8 were reissued Aug 28, 2026 under the April 1, 2026 order in 25-392-EL-AIR and the Aug 5, 2026 order in 26-113-EL-ATA; the new-load contract term is now the load ramp period plus 8 years.\",\"regulator\":\"Public Utilities Commission of Ohio (PUCO)\",\"docket_number\":\"24-508-EL-ATA\",\"filed_date\":\"2024-10-23\",\"decision_date\":\"2025-07-09\",\"min_load_mw\":25.0,\"customers\":[\"Amazon\",\"Google\",\"Microsoft\",\"Meta\"],\"summary\":\"First-in-the-nation, data-center-specific tariff requiring new large data centers to pay for at least 85% of their contracted capacity for a minimum term (the 2025 settlement said up to 12 years), even if they use less, to insulate other ratepayers from stranded-investment risk.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to data centers with aggregate monthly maximum demand above 25,000 kW.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"has an aggregate monthly maximum demand of greater than 25,000 kW\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Eligibility counts a single location or aggregated total customer contract capacity in the service territory above 25,000 kW; affiliated new loads are stacked.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"or an aggregated Total Customer Contract Capacity in Service Territory of greater than 25,000 kW\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"New-load contracts run at least the load ramp period plus 8 years (12 years with a 4-year ramp).\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"contracts under the Schedule shall be made for an initial period of not less than the Load Ramp Period plus 8 years\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Distribution demand charge in $/kW by voltage level (e.g., $9.05 secondary, $8.08 primary).\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"the product of the distribution demand charge and the monthly distribution billing demand\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"New load billing demand is at least 85% of load ramp contract capacity during ramp, then at least 85% of prior-11-month peak or a tiered Minimum Demand.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"monthly billing demand shall not be less than 85% of the customer's Load Ramp Contract Capacity\"},\"min_bill\":{\"status\":\"included\",\"detail\":\"Minimum monthly charge is the customer charge plus distribution demand charge times billing demand plus approved riders.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"The minimum monthly charge under this schedule shall be the sum of the customer charge, the product\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Customers without A-/A3 ratings and 10x liquidity post a guarantee, letter of credit or cash equal to 50% of total minimum charges over the term.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"equal to 50% of the total minimum charges for the full term of the contract\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customer signs a Letter of Agreement for network and customer-specific investment, or a CIAC agreement, before energization.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"sign a Letter of Agreement for network and customer- specific investment prior to energization\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Customer-specific and network investment is covered by a pre-energization Letter of Agreement or CIAC.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"sign a Letter of Agreement for network and customer- specific investment prior to energization\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Customer-owned behind-the-meter generation may offset contract capacity if instantaneous curtailment equipment is maintained.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"equipment must be in place and maintained through the term of the Electric Service Agreement to instantaneously curtail load\"},\"btm_generation\":{\"status\":\"included\",\"detail\":\"Customers may net behind-the-meter generation against contract capacity if equipment can instantaneously curtail load equal to the generation output.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"equipment must be in place and maintained through the term of the Electric Service Agreement to instantaneously curtail load\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Customers of 25,000 kW or more pay a one-time $10,000 to $100,000 fee per load study.\",\"source_url\":\"https://www.aepohio.com/company/about/rates/data-center-tariff/\",\"verbatim\":\"Ohio Power will charge a one-time fee of $10,000 to $100,000 for each load study\"},\"load_ramp_period\":{\"status\":\"included\",\"detail\":\"Load ramp period may not exceed four years, with minimums of 50/65/80/90% of contract capacity in years 1-4.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"until the customer reaches full contract capacity, which shall not exceed four years\"},\"resize_reassign\":{\"status\":\"partial\",\"detail\":\"After the initial term either party may request a contract capacity modification with three years' written notice.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"either party may request a modification to the Contract Capacity by providing written notice to the other party no later than three (3) years prior\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"After year five post-ramp, the customer can terminate by paying an exit fee equal to 36 months of minimum charges.\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"the customer chooses to pay an exit fee equal to minimum charges for 36 months after notice of termination\"},\"customer_type\":{\"status\":\"included\",\"detail\":\"Available only to customers that operate a data center (mobile data centers included).\",\"source_url\":\"https://www.aepohio.com/lib/docs/ratesandtariffs/Ohio/November_2026_Ohio_Power_Tariff_Book.pdf\",\"verbatim\":\"Service pursuant to this schedule is available for general service to customers that operate a Data Center\"}},\"additional_terms\":[{\"term\":\"Moratorium lift\",\"detail\":\"PUCO ordered AEP Ohio to immediately lift its moratorium on connecting new data centers.\",\"source_url\":\"https://puco.ohio.gov/news/puco-orders-aep-ohio-to-create-data-center-specific-tariff\"}],\"legislation\":[{\"policy_id\":\"oh-hb15-2025\",\"title\":\"Ohio House Bill 15 (2025)\",\"url\":\"https://ohiohouse.gov/committees/energy/bills/hb15\",\"citation\":\"HB 15, 136th General Assembly\",\"status\":\"Signed; effective Aug 14, 2025\",\"summary\":\"Restructured Ohio's electricity market (removed Electric Security Plans, enabled behind-the-meter self-power) to attract data centers while protecting ratepayers.\"}],\"source_url\":\"https://puco.ohio.gov/news/puco-orders-aep-ohio-to-create-data-center-specific-tariff\",\"source_title\":\"PUCO — Order directing AEP Ohio to create a data-center-specific tariff\",\"resources\":[{\"url\":\"https://www.aepohio.com/company/about/rates/data-center-tariff/\",\"title\":\"AEP Ohio — Data Center Tariff page\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"nv-energy-clean-transition-tariff\",\"utility\":\"NV Energy\",\"state\":\"NV\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Clean Transition Tariff (CTT)\",\"tariff_type\":\"Clean transition tariff\",\"status\":\"approved\",\"status_detail\":\"Approved by the Nevada PUC (docket 24-05022/24-05023), March 11, 2025.\",\"regulator\":\"Public Utilities Commission of Nevada (PUCN)\",\"docket_number\":\"24-05022 / 24-05023\",\"decision_date\":\"2025-03-11\",\"min_load_mw\":5.0,\"customers\":[\"Google\"],\"summary\":\"Optional tariff letting large industrial customers access new clean-energy resources by paying a premium; Google's 15-year service agreement would recover the cost of an enhanced-geothermal resource powering its data centers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to non-residential customers with an average annual hourly load of 5 MW or more on a 12-month rolling average.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"an average annual hourly load of five megawatts or more based on a consecutive twelve-month rolling average\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Non-governmental customers may aggregate load to reach 5 MW with Commission approval, case by case, if each facility averages at least 1 MW.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"A non-governmental Customer may use an aggregated load to meet the five megawatt threshold for this schedule with Commission approval\"},\"min_contract_duration\":{\"status\":\"partial\",\"detail\":\"Energy Supply Agreement term matches the life of the clean energy facility unless the application specifies otherwise.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"the CTT Facility(s), unless otherwise specified and explained in the\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Customers receive bundled service from named clean energy resources that NV Energy procures or generates under an Energy Supply Agreement.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"from which NV Energy will procure or generate energy for Customer that is approved by the PUCN\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Utility-held procurement of a named clean resource for the customer at a fixed CTT ESA rate.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"from which NV Energy will procure or generate energy for Customer that is approved by the PUCN\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Each Energy Supply Agreement application must identify system and/or non-participant benefits; no formula backstop appears in the stipulation text read.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"Be attached to an Application that identifies system and/or non-participant benefits that will result from the Energy Supply Agreement\"},\"no_harm_analysis\":{\"status\":\"partial\",\"detail\":\"Application must identify and support system and/or non-participant benefits of the Energy Supply Agreement.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AUlomseHlE%C3%81VcSKCkqwhsMynzoHCqBJyByXKOPmsBbTRGx%C3%898FCMCWTshIezNcJ2n%C3%89mydCqQ4rVu%C3%81MQ19H%C3%81W84o8%3D/\",\"verbatim\":\"Be attached to an Application that identifies system and/or non-participant benefits that will result from the Energy Supply Agreement\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — NV Energy Clean Transition Tariff (PUCN 24-05022/23)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"nv-energy-callisto-esa\",\"utility\":\"NV Energy\",\"state\":\"NV\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Callisto Energy Supply Agreement\",\"tariff_type\":\"Special contract / ESA\",\"status\":\"approved\",\"status_detail\":\"Approved. The PUCN's document portal (puc-onbase.nv.gov, the post-October-2023 docket system) lists for Docket 24-06014: STIPULATION filed 4/28/2025, DRAFT ORDER 5/7/2025, ORDER 5/14/2025, then compliance filings through 6/30/2025 and nothing since. The order itself (fetched from the portal 2026-09-22) states that the Commission, at its general session of May 13, 2025, 'accepts the Stipulation and grants the Application as modified by the Stipulation'; the stipulation was signed April 28, 2025 by Sierra Pacific Power, the Commission's Regulatory Operations Staff, the Attorney General's Bureau of Consumer Protection and counsel for Callisto Enterprises. Earlier passes that reported an 'April 29, 2026 open meeting' approval (from an AI news aggregator) had the year wrong; the two prior reversions to 'proposed' were correct to insist on a primary document. A second, separate Google ESA (Docket 26-06023, filed June 26, 2026) is tracked as nv-pucn-google-esa-2026.\",\"regulator\":\"Public Utilities Commission of Nevada (PUCN)\",\"docket_number\":\"24-06014\",\"decision_date\":\"2025-05-14\",\"summary\":\"A bespoke energy-supply agreement between Sierra Pacific Power (NV Energy) and Callisto Enterprises LLC — identified in the Commission's own order as Google — filed June 10, 2024 and approved by the PUCN by order adopted at its May 13, 2025 general session (entered in the docket May 14, 2025), accepting an April 28, 2025 stipulation among the joint applicants, Regulatory Operations Staff and the Bureau of Consumer Protection that resolved all issues in the docket. Exit terms tie the termination payment to the price difference between the procured resource and NV Energy's most recent approved renewable facilities (per the DOE/Berkeley Lab brief). A second, separate Google ESA (Docket 26-06023) was filed June 26, 2026.\",\"parameters\":{\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"An Energy Supply Agreement under the Clean Transition Tariff has the customer financially support a specific new geothermal project (Fervo).\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AZiVT6xWJfVUYu4f8QdFE%C3%89tjb1l5fEH6PYmtSFTpD%C3%816hmWZcKd1nvXGL2uyVctCuOtDiQpaLaVJ88TWvxWWREK4%3D/\",\"verbatim\":\"Google is providing significant financial support, which facilitates a new technology\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Utility-held ESA under the CTT in which Google's payments facilitate Fervo Energy's geothermal project.\",\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AZiVT6xWJfVUYu4f8QdFE%C3%89tjb1l5fEH6PYmtSFTpD%C3%816hmWZcKd1nvXGL2uyVctCuOtDiQpaLaVJ88TWvxWWREK4%3D/\",\"verbatim\":\"Google is providing significant financial support, which facilitates a new technology\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"NV Energy must report in each of its next three general rate cases how the ESA rate compares with base tariff rates and credits; any shortfall may be argued for differential cost allocation.\",\"verbatim\":\"detailing whether the Base Tariff General Rate portion of the Energy Supply Agreement rate has offset the generation credits in Statement O\"},\"no_harm_analysis\":{\"status\":\"partial\",\"detail\":\"Staff-required accounting in three subsequent rate cases tests whether the ESA's base tariff general rate portion offsets generation credits.\",\"verbatim\":\"detailing whether the Base Tariff General Rate portion of the Energy Supply Agreement rate has offset the generation credits in Statement O\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://puc-onbase.nv.gov/api/Document/AckzzzMp%C3%8123fDLAE0kmsnAEO%C3%89fAhCMjq0AtJbUUW3HNUBxPFerGSDgKdb01cE%C3%81h%C3%89Cco248s%C3%897sEJyOEG5R8uJyA%3D/\",\"source_title\":\"PUCN Order, Docket 24-06014 (general session May 13, 2025; entered May 14, 2025) — accepts Stipulation, grants Application as modified\",\"resources\":[{\"url\":\"https://puc-onbase.nv.gov/\",\"title\":\"PUCN Document Search portal — search type 'PUC - Public Search - Dockets', docket 24-06014\"},{\"url\":\"https://puc-onbase.nv.gov/api/Document/AZiVT6xWJfVUYu4f8QdFE%C3%89tjb1l5fEH6PYmtSFTpD%C3%816hmWZcKd1nvXGL2uyVctCuOtDiQpaLaVJ88TWvxWWREK4%3D/\",\"title\":\"PUCN Docket 24-06014 — Stipulation filed April 28, 2025 (Sierra Pacific, Staff, BCP, Callisto)\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Callisto ESA design elements\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"indiana-michigan-power-industrial-power-tariff\",\"utility\":\"Indiana Michigan Power (I&M, an AEP utility)\",\"state\":\"IN\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Tariff I.P. — Industrial Power (large-load settlement)\",\"tariff_type\":\"Data center / large-load tariff\",\"status\":\"approved\",\"status_detail\":\"IURC approved the settlement Feb 2025 (filed Nov 2024).\",\"regulator\":\"Indiana Utility Regulatory Commission (IURC)\",\"docket_number\":\"46097\",\"decision_date\":\"2025-02-26\",\"min_load_mw\":70.0,\"customers\":[\"Amazon\",\"Google\",\"Microsoft\"],\"summary\":\"A 'landmark' settlement among I&M, the state consumer counselor, Citizens Action Coalition, Amazon, Google, Microsoft and the Data Center Coalition setting minimum-take, collateral and exit terms for large loads, plus low-income community payments.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to Tariff I.P. customers with contract capacity of 70 MW or more at one plant or 150 MW aggregated.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"contract capacity greater than or equal to 70 MW at an individual plant or 150MW on an aggregated basis\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"I&M decides, with reasonable discretion, which premises to aggregate (common owner, parent, local infrastructure or control).\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"The Company will exercise reasonable discretion when choosing to aggregate premises\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Initial contract term of at least 12 years, starting after any load ramp period.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"Initial Contract Term will be made for a period of not less than 12 years\"},\"load_ramp_period\":{\"status\":\"included\",\"detail\":\"Customer may designate a load ramp period of up to five years before the initial term begins.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"A Large Load Customer may designate a Load Ramp Period, which can be no greater than five years\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Minimum charge includes a $/kW Step 1 Embedded Capacity Charge ($10.959/kW at transmission voltage) times monthly billing demand, plus demand charges.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"the product of the Step 1 Embedded Capacity Charge and the Monthly Billing Demand\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Monthly billing demand is at least 80% of contract capacity or 80% of the highest billing demand in the prior 11 months.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"in no event be less than the greater of (a) 80 percent of the Large Load Customer's contract capacity\"},\"min_bill\":{\"status\":\"included\",\"detail\":\"Minimum monthly charge per plant is the sum of the service charge, minimum demand charge, embedded capacity charge and demand-related riders applied to billing demand.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"Large Load Customers are subject to a minimum monthly charge for each plant equal to the sum of\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Collateral is required unless the customer has A-/A3 ratings and liquidity above ten times the requirement; guarantee, letter of credit or cash are accepted.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"a Large Load Customer with a credit rating of at least A- from S&P and A3 from Moody's and liquidity greater than ten times the Collateral Requirement shall be exempt\"},\"resize_reassign\":{\"status\":\"included\",\"detail\":\"After year five, customer may cut contract capacity by up to 20% without an exit fee on 42 months' notice; I&M will try to re-assign released capacity to new large loads.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"reduce its contract capacity at any time after the first five years by up to 20%, in total\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Termination or reductions beyond 20% after year five carry an exit fee equal to the remaining minimum charge for 1 to 5 years.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"subject to payment of a capacity reduction/termination fee\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Full planning studies, including steady-state and dynamic studies, are paid solely by the large load customer.\",\"source_url\":\"https://secure.in.gov/iurc/files/ord_46097_021925.pdf\",\"verbatim\":\"Full Planning Studies, including steady-state and dynamic studies, required because of the potential addition of a Large Load Customer shall be paid solely by the Large Load Customer\"}},\"additional_terms\":[{\"term\":\"Economic development payments\",\"detail\":\"Amazon, Google and Microsoft each provide $500,000/year for 5 years to the Indiana Community Action Association for weatherization of income-qualified customers.\"}],\"legislation\":[],\"source_url\":\"https://www.aep.com/news/stories/view/10037/\",\"source_title\":\"AEP — Indiana Michigan Power receives order in large-load settlement\",\"resources\":[{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"duke-energy-indiana-meta-esa\",\"utility\":\"Duke Energy Indiana\",\"state\":\"IN\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Electric Service Agreement with Blocke, LLC (Meta)\",\"tariff_type\":\"Special contract / ESA\",\"status\":\"approved\",\"regulator\":\"Indiana Utility Regulatory Commission (IURC)\",\"docket_number\":\"45975\",\"decision_date\":\"2024-04-24\",\"customers\":[\"Meta\"],\"summary\":\"A special retail electric service agreement, approved by the IURC in Cause 45975 on April 24, 2024, that pairs the customer's load with dedicated power purchase agreements kept out of the utility's resource plan. The order names the customer as Blocke, LLC at River Ridge Commerce Center in Jeffersonville, with an unnamed parent; the Meta attribution comes from Berkeley Lab's 2025 brief, not the order.\",\"parameters\":{\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Market service demand fee equals the customer's highest billing-period demand times a negotiated $/kW-month fee fixed over the agreement.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"a market service demand fee based on Customer's highest demand in the billing period multiplied by demand fee of an amount per kilowatt-month\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customer reimburses Duke for capacity acquired on its behalf, non-networked costs, and third-party capacity-shortfall costs.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"Customer will reimburse Duke Energy Indiana for all costs for acquiring the capacity on its behalf\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Customer reimburses all costs of acquiring capacity on its behalf.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"Customer will reimburse Duke Energy Indiana for all costs for acquiring the capacity on its behalf\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Non-networked costs Duke incurs are reimbursed by the customer.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"non-networked costs incurred by Petitioner will be reimbursed by Customer\"},\"dca_network_transmission\":{\"status\":\"partial\",\"detail\":\"Customer pays its allocated share of transmission costs (MISO OATT rate plus Schedule 26/26-A charges); network upgrades are coordinated as the project completes.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"(3) Customer's allocated share of transmission costs, including the MISO OATT Rate Charge\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Duke procures a percentage of the customer's annual load from new renewable resources via PPAs under a tranche agreement, costs recovered from the customer.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"with renewable energy from new renewable resources through purchased power agreements\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Duke and customer select renewable facilities by RFP; Duke signs the PPAs and recovers their full cost from the customer.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"with renewable energy from new renewable resources through purchased power agreements\"},\"exit_fee\":{\"status\":\"partial\",\"detail\":\"The agreement provides for termination on specified material load reductions and protections against customer default and early termination; the fee terms are confidential.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"provide for termination in the event of material load reductions as specified\"},\"price_premium\":{\"status\":\"included\",\"detail\":\"Agreement requires the customer to cover incremental costs of service plus contribute to Duke's fixed-cost recovery (Commission finding).\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"the Agreement requires that Customer cover the incremental costs of providing service to it, as well as contributing to Petitioner's recovery of fixed costs\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Order describes structural protections to prevent adverse impacts on other customers; specific mechanism is confidential.\",\"source_url\":\"https://www.in.gov/iurc/files/ord_45975_042424.pdf\",\"verbatim\":\"structural protections to prevent adverse impacts on other customers\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Duke Energy Indiana / Meta ESA (IURC 45975)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"xcel-minnesota-competitive-response-rider\",\"utility\":\"Xcel Energy (Northern States Power — Minnesota)\",\"state\":\"MN\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Competitive Response Rider / Google Electric Service Agreement\",\"tariff_type\":\"Large-load rider\",\"status\":\"approved\",\"regulator\":\"Minnesota Public Utilities Commission (MPUC)\",\"docket_number\":\"19-39\",\"min_load_mw\":10.0,\"customers\":[\"Google\"],\"summary\":\"A negotiated, discounted large-load rider for customers that could otherwise obtain third-party supply, with a hold-harmless test ensuring incremental costs to serve the customer are offset by incremental revenue.\",\"parameters\":{\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Minnesota PUC states the statute requires the negotiated rate to cover incremental costs of service, with fixed costs spread over a larger customer base.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/37577b1\",\"verbatim\":\"the statute requires that the proposed rate covers incremental costs of service, and fixed costs will be spread over a larger set of customers\"},\"price_premium\":{\"status\":\"partial\",\"detail\":\"Per the PUC release, the negotiated rate must at least cover incremental costs of service.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/37577b1\",\"verbatim\":\"the statute requires that the proposed rate covers incremental costs of service\"}},\"additional_terms\":[{\"term\":\"Contract term flexibility\",\"detail\":\"Customers may renew for an additional 10 years if they maintain ≥75 MW firm peak demand during their final 2 years.\"}],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Xcel Minnesota Competitive Response Rider (MPUC 19-39)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"idaho-power-brisbie-esa\",\"utility\":\"Idaho Power\",\"state\":\"ID\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Brisbie Energy Services Agreement / Clean Energy Your Way\",\"tariff_type\":\"Special contract / ESA\",\"status\":\"approved\",\"regulator\":\"Idaho Public Utilities Commission (IPUC)\",\"docket_number\":\"IPC-E-21-42\",\"customers\":[\"Brisbie (data center)\"],\"summary\":\"An energy-services agreement in which Idaho Power procures renewable resources on a data center's behalf and connects them to its transmission system; the customer pays for the resources and its load-ratio share of the grid, and is credited for system value.\",\"parameters\":{\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"ESA includes demand charges designed primarily to recover the cost of capacity; Staff recommended approving them as proposed.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"The demand charges are designed to primarily recover the cost of capacity\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Under a Construction Agreement, transmission construction and ongoing O&M up to the point of delivery are borne by the customer, not other ratepayers (Staff finding).\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"provide ongoing electric service to the Brisbie data center, including transmission construction\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Costs to connect the Brisbie data center, including transmission construction up to the point of delivery, are not borne by other ratepayers.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"provide ongoing electric service to the Brisbie data center, including transmission construction\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Idaho Power procures renewable resources to support the customer's load under a standard procurement agreement, with credits for excess generation and capacity contribution.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"authority to procure renewable resources for the purpose of supporting Brisbie's energy needs under a standard procurement agreement\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Utility-held procurement of renewable resources for the customer's data center load; customer claims 100% of the RECs.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"authority to procure renewable resources for the purpose of supporting Brisbie's energy needs under a standard procurement agreement\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Application sought cost recovery mechanisms to protect existing customers from cost shifting; Staff reviewed the ESA to ensure other customers are not harmed.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"the cost recovery mechanisms necessary to protect existing customers from unreasonable cost shifting\"},\"marginal_cost\":{\"status\":\"included\",\"detail\":\"Load above the first 20 MW (Block 2) is priced at a marginal cost rate; the first 20 MW is priced at Schedule 19T embedded-cost energy rates.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"Any load exceeding 20 MWs (Block 2) is priced at a marginal cost rate using the\"},\"no_harm_analysis\":{\"status\":\"included\",\"detail\":\"Idaho Power filed a No-Harm Analysis showing a $17.8 million benefit to customers over 10 years; Staff found it insufficient as a primary basis because it used one set of assumptions.\",\"source_url\":\"https://puc.idaho.gov/Fileroom/PublicFiles/ELEC/IPC/IPCE2142/OrdNotc/20230511Final_Order_No_35777.pdf\",\"verbatim\":\"showed that the system with the ESA could provide a $17.8 million benefit to customers over a 10-year period\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Idaho Power Brisbie ESA (IPUC IPC-E-21-42)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"montana-dakota-high-density-demand-response\",\"utility\":\"Montana-Dakota Utilities (MDU)\",\"state\":\"ND\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"High Density Contracted Demand Response Rate\",\"tariff_type\":\"Data center tariff\",\"status\":\"approved\",\"regulator\":\"North Dakota Public Service Commission (ND PSC)\",\"docket_number\":\"PU-22-337\",\"summary\":\"A rate available only to data-center-type facilities housing high-density computer-processing technology, with a high minimum load factor and an up-front contribution toward the facilities built to serve them.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Available to data-center-type facilities with expected demand of at least 10,000 kW (10 MW) per month at a single delivery point (as filed).\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"an expected demand of at least 10,000 Kw per month metered at a single delivery point\"},\"load_factor_threshold\":{\"status\":\"included\",\"detail\":\"Expected minimum load factor of 85% (as filed).\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"an expected minimum load factor of 85%\"},\"customer_type\":{\"status\":\"included\",\"detail\":\"Rate is limited to data center-type facilities housing high density computer processing technology (originally prompted by blockchain mining inquiries).\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"data center-type facilities housing high density computer processing technology\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Electric service agreement term of at least three and at most five years (as filed).\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"shall have a minimum term of three years but not\"},\"collateral\":{\"status\":\"partial\",\"detail\":\"Each service agreement sets a deposit required before service starts; amount is not fixed in the tariff.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"The deposit amount required prior to the commencement of service\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customer pays a CIAC in advance covering estimated cost of installing and removing service facilities, with salvage credit.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"The Company shall require a contribution in aid of construction (CIAC) from the customer, in advance of the construction of any facilities\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"CIAC in advance of construction covers service facilities for the customer.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"The Company shall require a contribution in aid of construction (CIAC) from the customer, in advance of the construction of any facilities\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Rate is an interruptible demand-response service in which the customer's load can be curtailed (load flexibility is the customer-specific service element).\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"Company must be able to interrupt customer's service under this rate schedule for up to 200 hours annually\"},\"load_flexibility\":{\"status\":\"included\",\"detail\":\"Utility may interrupt service up to 200 hours per year (or as in the ESA), with a penalty of the greater of $10/kW or the MISO penalty for non-performance.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"Company must be able to interrupt customer's service under this rate schedule for up to 200 hours annually\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Application states charges are designed so Montana-Dakota and its other customers are not harmed; the ESA must be approved by the PSC.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"ensuring Montana-Dakota and the Company's other North Dakota customers are not harmed\"},\"marginal_cost\":{\"status\":\"included\",\"detail\":\"Customers are billed any and all incremental costs required to provide service each month, as set in the ESA.\",\"source_url\":\"https://www.psc.nd.gov/webdocs/case/22-0337/001-010.pdf\",\"verbatim\":\"shall be billed any and all incremental costs required to provide electric service to customers each month\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — MDU High Density Contracted Demand Response (ND PSC PU-22-337)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"black-hills-large-power-contract-service\",\"utility\":\"Black Hills Energy\",\"state\":\"WY\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Power Contract Service Tariff\",\"tariff_type\":\"Large-load tariff\",\"status\":\"approved\",\"regulator\":\"Wyoming Public Service Commission (WY PSC)\",\"docket_number\":\"20003-146-ET-15\",\"summary\":\"Cheyenne Light, Fuel and Power's Large Power Contract Service (Wyoming Tariff No. 14, Schedule LPCS) serves loads of 5,000 kW or more without the utility building generation for them: capacity costs are assigned directly to the customer, which must back its load with eligible resources such as on-site back-up generators. Berkeley Lab's 2025 brief described the excess-capacity trigger as 35 MW; the current tariff text uses a 5,000 kW floor and a 115% capacity requirement.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to new or existing load with expected capacity requirements of 5,000 kW or greater (on top of the load needed to qualify for ICS or ITS service).\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"with expected capacity requirements of 5,000 kW or greater\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Costs of all eligible capacity resources, with associated transmission and ancillary costs, are directly assigned to and collected from the customer; LPCS customers are not combined with other classes in cost-of-service studies.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"will be directly assigned to and collected from the Customer\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Capacity resource costs, whether Company-owned or third-party procured, are directly assigned to the customer.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"will be directly assigned to and collected from the Customer\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Transmission costs are directly assigned or allocated to the customer on load-ratio share; TCAM sets the Company's transmission costs.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"either directly assigned to the customer or allocated to the customer for network service on a load ratio share\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Customer must provide back-up capacity through Eligible Capacity Resources on its property or delivered by firm transmission rights.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"the Customer must agree to provide back-up service for the Customer's load and to maintain the reliability of the back-up service\"},\"btm_generation\":{\"status\":\"included\",\"detail\":\"Eligible capacity resources include customer-owned back-up generators with on-call fuel supply, customer-supplied air permits and nameplate capacity credit.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"Customer owned back-up generators or Company-owned generators built specifically for one\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Eligible resources include renewable resources procured through a PPA backed by physical resources, battery storage, and capacity contracts.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"Renewable resources that are Company owned or procured through a Purchased Power Agreement backed by physical resources\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Company may require a deposit or other credit support such as a performance guarantee or letter of credit, held as security.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"The Company may require a deposit or other credit support from the customer\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Negotiated Microgrid Management Fee in $/kW-month on peak demand; capacity and energy charges pass through actual costs.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"Microgrid Management Fee - $/kW-mo., negotiated rate based on the peak demand of the load served\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Ring-fencing: LPCS customers are excluded from class cost of service studies and costs are assigned individually on cost causation.\",\"source_url\":\"https://wwwredir.blackhillsenergy.com/sites/blackhillsenergy.com/files/clfp_electric.pdf\",\"verbatim\":\"Customers taking service under this Rate Schedule will not be combined with other retail customers for purposes of class cost of service studies\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Black Hills Large Power Contract Service (WY PSC 20003-146-ET-15)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"pge-large-nonres-green-energy-affinity-rider\",\"utility\":\"Portland General Electric (PGE)\",\"state\":\"OR\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Nonresidential Green Energy Affinity Rider (Voluntary Renewable Energy Tariff)\",\"tariff_type\":\"Green tariff\",\"status\":\"approved\",\"regulator\":\"Public Utility Commission of Oregon (OPUC)\",\"docket_number\":\"UM 1953\",\"summary\":\"A voluntary green tariff giving large nonresidential customers a subscription share of a new renewable facility, or access to clean energy through customer- or utility-signed power-purchase agreements.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Nonresidential customers whose aggregate demand across all retail schedules exceeds 30 kW; the customer-selected option requires more than 10 aMW of load.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"each of whose aggregate demand across all retail schedules exceeds 30kW\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Customers with multiple accounts, some under 30 kW, may aggregate all nonresidential accounts.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"will be allowed to aggregate all Nonresidential accounts\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Subscribing customer elects a term of 5 to 20 years, consistent with the renewable supplier contract or resource life.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"for a term between 5 and 20 years\"},\"direct_cost_assignment\":{\"status\":\"partial\",\"detail\":\"Rider charges pass the subscribing customer the cost of acquiring the renewable resource and running the program.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"The Rider rate will pass to Subscribing Customers the costs of acquiring the renewable energy resource and operating this supplemental program\"},\"dca_generation_capacity\":{\"status\":\"partial\",\"detail\":\"Cost of the dedicated renewable resource is charged to the subscriber, net of energy and capacity value credits.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"The Rider rate will pass to Subscribing Customers the costs of acquiring the renewable energy resource and operating this supplemental program\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Customer subscribes to a share of a new renewable facility, either PGE-procured (PSO) or customer-selected (CSO).\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"a Nonresidential Customer may purchase a subscription share of a new renewable\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Customer Supply Option lets customers with more than 10 aMW identify and select a resource contracted as a PPA or company-owned resource.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"means a resource identified and selected by the Customer\"},\"exit_fee\":{\"status\":\"partial\",\"detail\":\"Early termination or default is governed by termination and default provisions in the subscription agreement; no fee formula in the tariff.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"shall be subject to termination and default\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Non-subscribing customers bear no resource, administrative or program costs apart from the energy and capacity value credits.\",\"source_url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa161511.pdf\",\"verbatim\":\"Non-subscribing Customers will not be subject to resource costs, administrative costs, or\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — PGE Green Energy Affinity Rider (OPUC UM 1953)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"entergy-mississippi-large-power-rate\",\"utility\":\"Entergy Mississippi\",\"state\":\"MS\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Power Rate Schedule\",\"tariff_type\":\"Large-load tariff\",\"status\":\"approved\",\"status_detail\":\"Not found on Entergy Mississippi's current tariff index (checked Nov 16, 2026), which lists Large General Service C-29, Alternate Large General Service ALGS-10 (5,000 to 35,000 kW) and High Load Factor HLF-7; Berkeley Lab's August 2026 update does not list it. The record rests on the 2025 brief alone.\",\"regulator\":\"Mississippi Public Service Commission (MS PSC)\",\"docket_number\":\"2014-UN-132\",\"summary\":\"Entergy Mississippi's large-power rate schedule, which sets a 30 MW minimum load requirement for service. Entergy maintains data centers pay their full cost of service — a claim contested by ratepayer advocates (see the Ratepayer Protection view).\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Berkeley Lab's 2025 brief lists a 30 MW minimum load for this schedule.\",\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"verbatim\":\"Entergy Mississippi’s Large Power Rate Schedule has a 30 MW minimum load requirement.\"}},\"additional_terms\":[{\"term\":\"Contested cost recovery\",\"detail\":\"A May 2026 Synapse Energy Economics report estimated ~$38M in data-center-related costs already charged to Entergy Mississippi residential ratepayers; Entergy disputes the finding.\",\"source_url\":\"https://desotocountynews.com/mississippi-news/data-centers-likely-increasing-mississippi-power-rates-new-report-claims/\"}],\"legislation\":[],\"source_url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"source_title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025) — Entergy Mississippi Large Power Rate (MS PSC 2014-UN-132)\",\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"georgia-power-large-load-rules\",\"utility\":\"Georgia Power\",\"state\":\"GA\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Rules for new large-load customers (>100 MW)\",\"tariff_type\":\"Large-load rule / tariff\",\"status\":\"approved\",\"status_detail\":\"Georgia PSC approved the rule Jan 23, 2025 (Docket 55378).\",\"regulator\":\"Georgia Public Service Commission (GA PSC)\",\"docket_number\":\"55378\",\"decision_date\":\"2025-01-23\",\"min_load_mw\":100.0,\"summary\":\"A PSC rule allowing Georgia Power to apply special terms and conditions to any new customer using more than 100 MW, requiring large-load customers to pay the transmission and distribution costs they drive as construction progresses.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Special terms apply to new customers using more than 100 MW.\",\"verbatim\":\"any new customers using more than 100\"},\"min_contract_duration\":{\"status\":\"partial\",\"detail\":\"Rule allows contract lengths longer than the standard 5 years, up to 15 years; the length is not fixed by the rule as summarized.\",\"verbatim\":\"longer contract lengths (from 5-year contracts to 15-year contracts)\"},\"min_bill\":{\"status\":\"partial\",\"detail\":\"Rule allows minimum billing requirements for high-load customers; levels are not stated in the PSC release.\",\"verbatim\":\"minimum billing requirements for high-load customers\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Large-load customers pay site-specific costs plus upstream generation, transmission and distribution costs as construction progresses.\",\"verbatim\":\"the data centers would pay for costs incurred by upstream generation, transmission and distribution to these large-load power users\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Customers pay costs incurred by upstream generation as construction progresses.\",\"verbatim\":\"the data centers would pay for costs incurred by upstream generation, transmission and distribution to these large-load power users\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Customers pay costs incurred by upstream transmission as construction progresses.\",\"verbatim\":\"the data centers would pay for costs incurred by upstream generation, transmission and distribution to these large-load power users\"},\"dca_interconnection\":{\"status\":\"partial\",\"detail\":\"Customers pay site-specific costs in addition to upstream costs.\",\"verbatim\":\"In addition to site specific costs\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"PSC states the rule is meant to protect ratepayers from cost shifting; no formula backstop is described.\",\"verbatim\":\"charge new data centers in a manner that will protect ratepayers from cost shifting\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://psc.ga.gov/site/assets/files/8617/media_advisory_data_centers_rule_1-23-2025.pdf\",\"source_title\":\"Georgia PSC — Media advisory: rule allowing new power-usage terms for data centers\",\"resources\":[{\"url\":\"https://psc.ga.gov/facts-advanced-search/docket/?docketId=55378\",\"title\":\"Georgia PSC — Docket 55378\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"dominion-virginia-gs5-rate-class\",\"utility\":\"Dominion Energy Virginia\",\"state\":\"VA\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Rate Schedule GS-5 (large-load / data-center rate class)\",\"tariff_type\":\"Data center rate class\",\"status\":\"approved\",\"status_detail\":\"SCC approved the new rate class in the 2025 biennial review (Nov 2025); effective Jan 1, 2027.\",\"regulator\":\"Virginia State Corporation Commission (SCC)\",\"decision_date\":\"2025-11-25\",\"min_load_mw\":25.0,\"summary\":\"A new rate class for the largest electricity users (over 25 MW), including data centers, requiring minimum demand commitments, a 14-year contract term and up-front collateral so grid-upgrade costs driven by data centers are not shifted to other customers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"GS-5 applies to customers demanding 25 MW or more, effective Jan 1, 2027.\",\"verbatim\":\"the new GS-5 rate class will comprise customers demanding 25 megawatts or more\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"New large load customers contracting on or after Jan 1, 2027 must take and pay for service for at least 14 years.\",\"source_url\":\"https://www.scc.virginia.gov/media/sccvirginiagov-home/about-the-scc/fact-sheets/scc-data-center-initiatives-02-2026.pdf\",\"verbatim\":\"will be obligated to take, and pay, for electric service for at least 14 years\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Large customers pay at least 85% of contracted distribution and transmission demand and 60% of generation demand regardless of usage.\",\"verbatim\":\"a minimum of 85% of contracted distribution and transmission demand, and 60% of generation demand\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Customers without sufficient credit may be required to guarantee funds covering up to 60% of minimum charges over the contract term.\",\"source_url\":\"https://www.scc.virginia.gov/media/sccvirginiagov-home/about-the-scc/fact-sheets/scc-data-center-initiatives-02-2026.pdf\",\"verbatim\":\"guarantee funds intended to cover up to 60% of the customer's minimum charges over their contract term\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"SCC describes the new class and special provisions as minimizing the risk that infrastructure costs for large loads are recovered from other customers; it also ordered alternative cost allocation proposals.\",\"source_url\":\"https://www.scc.virginia.gov/media/sccvirginiagov-home/about-the-scc/fact-sheets/scc-data-center-initiatives-02-2026.pdf\",\"verbatim\":\"further minimize the risk that infrastructure costs incurred primarily to serve large load customers could be recovered from other customers\"}},\"additional_terms\":[],\"legislation\":[{\"title\":\"Virginia SCC Data Center Initiatives (2025–2026)\",\"url\":\"https://www.scc.virginia.gov/media/sccvirginiagov-home/about-the-scc/fact-sheets/scc-data-center-initiatives-02-2026.pdf\",\"citation\":\"SCC fact sheet\",\"status\":\"Active\",\"summary\":\"SCC's program of measures to ensure data centers pay their own costs, the policy backdrop for the GS-5 rate class.\"}],\"source_url\":\"https://www.scc.virginia.gov/about-the-scc/newsreleases/release/scc-issues-order-on-dev-biennial-review-2025/scc-rules-in-dev-biennial-review-case.html\",\"source_title\":\"Virginia SCC — Order on Dominion's 2025 biennial review (new data-center rate class)\",\"resources\":[{\"url\":\"https://www.scc.virginia.gov/media/sccvirginiagov-home/about-the-scc/fact-sheets/scc-data-center-initiatives-02-2026.pdf\",\"title\":\"Virginia SCC — Data Center Initiatives fact sheet\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"texas-puct-large-load-interconnection\",\"utility\":\"ERCOT transmission & distribution utilities (statewide)\",\"state\":\"TX\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large-load interconnection standards (SB 6 implementation)\",\"tariff_type\":\"Interconnection rule / statute\",\"status\":\"approved\",\"status_detail\":\"Signed by Governor Abbott June 20, 2025, effective immediately (Acts 2025, 89th R.S., ch. 953). The PUCT has adopted the implementing rule, 16 TAC §25.194 (Project No. 58481). The adopted rule sets a $100,000 study fee and financial security of $50,000 per MW of requested peak demand, returned or forfeited under set conditions.\",\"regulator\":\"Public Utility Commission of Texas (PUCT) / ERCOT\",\"decision_date\":\"2025-06-20\",\"summary\":\"Texas Senate Bill 6 directs the PUCT to create interconnection standards for new loads of 75 MW or greater, imposing interconnection fees, financial security, full cost responsibility and emergency curtailment obligations on data centers and other large loads.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Rule applies to large load customers with total expected non-coincident peak demand of 75 MW or more at a single site.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"An entity requesting a new or expanded interconnection where the customer’s total expected non-coincident peak demand at a single site is equal to or exceeds 75 MW\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Financial security of $50,000 per MW of requested peak demand (or incremental increase) must be posted with the intermediate agreement; further security is posted at SLLIA execution; unused security is returned or forfeited under set conditions.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"must post financial security with the interconnecting DSP or the interconnecting TSP in the amount of $50,000 per MW of the requested peak demand for new interconnection requests\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Customers pay a $100,000 study fee before the request is included in an interconnection study; unused study amounts are returned within 60 days.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"A large load customer must pay a study fee of $100,000 to the interconnecting DSP or the interconnecting TSP for transmission studies\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customers pay direct interconnection costs through cash CIAC with no allowance offsetting it.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"A large load customer must pay all direct interconnection costs through CIAC, with no standard or other allowance offered to offset the customer’s CIAC payments.\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Direct interconnection costs (significant equipment and services) are paid as non-refundable CIAC in cash.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"CIAC must be paid in the form of a direct cash payment.\"},\"min_billing_demand\":{\"status\":\"partial\",\"detail\":\"The standard large load interconnection agreement must acknowledge that the customer will pay the large load minimum billing demand set in 16 TAC 25.193; the percentage is in that separate rule.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"The SLLIA must include a term of acknowledgment and agreement that the large load customer will pay the large load minimum billing demand described in §25.193\"},\"load_forecast_requirement\":{\"status\":\"partial\",\"detail\":\"Customers must disclose a month-and-year schedule for phased energization of requested peak demand and give progress updates when requested; no periodic forecast cadence is set.\",\"source_url\":\"https://ftp.puc.texas.gov/public/puct-info/agency/rulesnlaws/subrules/electric/25.194/58481adt.pdf\",\"verbatim\":\"A large load customer must provide updates or progress reports to the interconnecting DSP or the interconnecting TSP when requested.\"},\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"Statute directs standards on load curtailment and on-site backup generation deployment during emergencies.\",\"source_url\":\"https://capitol.texas.gov/tlodocs/89R/billtext/html/SB00006F.htm\",\"verbatim\":\"require the large load customer to either deploy the customer's on-site backup generating facilities or curtail load.\"},\"load_flexibility\":{\"status\":\"partial\",\"detail\":\"SB 6 allows ERCOT to direct large loads (75 MW+) to curtail or deploy on-site backup generation in emergencies and requires a competitive demand-reduction procurement program.\",\"source_url\":\"https://capitol.texas.gov/tlodocs/89R/billtext/html/SB00006F.htm\",\"verbatim\":\"requires each large load to remain curtailed for the duration of the energy emergency alert event or until the load can be recalled safely\"}},\"additional_terms\":[{\"term\":\"Emergency curtailment\",\"detail\":\"Utilities must develop protocols allowing large loads interconnected after Dec 31, 2025 to be curtailed during emergencies.\"},{\"term\":\"Co-location oversight\",\"detail\":\"Expands PUCT/ERCOT oversight of behind-the-meter and co-located generation arrangements.\"}],\"legislation\":[{\"policy_id\":\"tx-sb6-2025\",\"title\":\"Texas Senate Bill 6 (2025)\",\"url\":\"https://capitol.texas.gov/tlodocs/89R/billtext/pdf/SB00006H.pdf\",\"citation\":\"SB 6, 89th Legislature\",\"status\":\"Signed June 20, 2025\",\"summary\":\"Overhauls large-load interconnection, transmission cost allocation and co-location rules in ERCOT.\"}],\"source_url\":\"https://www.lrl.texas.gov/legis/billsearch/BillDetails.cfm?legSession=89-0&billTypeDetail=SB&billnumberDetail=6\",\"source_title\":\"Texas Legislative Reference Library — SB 6 (89th R.S.) bill history\",\"resources\":[{\"url\":\"https://capitol.texas.gov/BillLookup/History.aspx?LegSess=89R&Bill=SB6\",\"title\":\"Texas Legislature — SB 6 bill history\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"ferc-talen-amazon-susquehanna-isa\",\"utility\":\"Talen Energy / PPL / PJM (Amazon co-location)\",\"state\":\"PA\",\"jurisdiction_level\":\"federal\",\"tariff_name\":\"Amended Interconnection Service Agreement — Susquehanna co-location\",\"tariff_type\":\"Co-location interconnection agreement (federal)\",\"status\":\"rejected\",\"status_detail\":\"FERC rejected the amended ISA 2–1 on Nov 1, 2024 (189 FERC ¶ 61,078).\",\"regulator\":\"Federal Energy Regulatory Commission (FERC)\",\"docket_number\":\"ER24-2172\",\"decision_date\":\"2024-11-01\",\"min_load_mw\":480.0,\"customers\":[\"Amazon (AWS)\"],\"summary\":\"A federal (not state) co-location case included as the LBL brief's reference point (FERC AD24-11-000): PJM/PPL/Talen sought to raise the co-located load for an Amazon data center at the Susquehanna nuclear plant from 300 MW to 480 MW. FERC rejected the amended ISA, finding PJM had not met its burden to justify the non-standard arrangement.\",\"parameters\":{\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"Proposed ISA amendment would let a co-located load take supply from the adjacent Susquehanna generation behind the point of interconnection; the amendment was rejected.\",\"verbatim\":\"to increase the amount of Co-Located Load from 300 megawatts (MW) to 480 MW and to make revisions related to the treatment of this Co-Located Load\"},\"btm_generation\":{\"status\":\"partial\",\"detail\":\"Co-located load of up to 480 MW (up from 300 MW) on the generator side of the interconnection point; FERC rejected the non-conforming amendment on Nov 1, 2024.\",\"verbatim\":\"we find that PJM has not demonstrated that the proposed non-conforming provisions in the Amended ISA are necessary deviations from the pro forma ISA\"}},\"additional_terms\":[{\"term\":\"Cost-allocation dispute\",\"detail\":\"FERC majority held PJM failed to show its standard ISA was inadequate; the dissent called it a 'first-of-its-kind' configuration needing bespoke review.\",\"source_url\":\"https://www.ferc.gov/sites/default/files/2024-11/20241101-3061_ER24-2172-000.pdf\"},{\"term\":\"Co-location rulemaking\",\"detail\":\"Spurred FERC's broader inquiry into large loads co-located at generating facilities (Docket AD24-11-000).\"}],\"legislation\":[],\"source_url\":\"https://www.ferc.gov/sites/default/files/2024-11/20241101-3061_ER24-2172-000.pdf\",\"source_title\":\"FERC — Order rejecting amended ISA, 189 FERC ¶ 61,078 (Docket ER24-2172)\",\"resources\":[{\"url\":\"https://www.utilitydive.com/news/ferc-interconnection-isa-talen-amazon-data-center-susquehanna-exelon/731841/\",\"title\":\"Utility Dive — FERC rejects Talen–Amazon Susquehanna interconnection pact\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"pa-puc-large-load-model-tariff\",\"utility\":\"Pennsylvania electric distribution companies (statewide model framework)\",\"state\":\"PA\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Load Model Tariff Framework\",\"tariff_type\":\"Statewide model tariff / large-load framework\",\"status\":\"approved\",\"status_detail\":\"Final order entered May 13, 2026 (adopted 5-0 on April 30, 2026). A model framework Pennsylvania EDCs may incorporate into utility-specific tariff filings, subject to Commission review.\",\"regulator\":\"Pennsylvania Public Utility Commission (PA PUC)\",\"docket_number\":\"M-2025-3054271\",\"decision_date\":\"2026-05-13\",\"min_load_mw\":50.0,\"summary\":\"First-of-its-kind statewide model tariff framework giving Pennsylvania's electric distribution companies consistent guidance for serving large loads — customers above 50 MW individually or 100 MW in aggregate — with cost-causation, financial-assurance, and interconnection-study standards to protect existing ratepayers from stranded costs.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Model tariff applies at 50 MW individually; utility may apply it below the threshold case by case.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"This tariff is applicable to customers at or over 50 MW individually or 100 MW in the aggregate.\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"100 MW threshold applies to multiple closely located customers in aggregate; behind-the-meter generation is excluded from the threshold calculation.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"multiple closely located customers with maximum Contract Capacity of 100 MW in the aggregate\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Initial Contract Term of at least five years, starting after the load ramp period; company may require longer to recover its investment.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"A Large Load Customer’s Initial Contract Term should be made for a period of not less than five (5) years.\"},\"monthly_demand_charge\":{\"status\":\"partial\",\"detail\":\"Customers may be charged higher monthly demand charges than the minimum so the utility fully recovers fixed costs; rates are set in each utility's own tariff.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Large Load Customers may be subject to higher monthly demand changes to allow the utility to fully recover fixed costs associated with serving the Large Load Customers’ load.\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Monthly billing demand is no less than the greater of 80% of contract capacity or 80% of the highest billing demand in the prior 11 months.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Eighty (80) percent of the Large Load Customer's contract capacity specified for the applicable period of the Contract Term\"},\"min_bill\":{\"status\":\"partial\",\"detail\":\"Minimum monthly demand charge equal to 80% of contracted demand; customer pays minimum charges during the initial term even if it curtails, suspends or terminates.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Large Load Customers will be subject to a minimum monthly demand charge equal to 80% of the contracted demand.\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Collateral must fully cover Network Improvement and Interconnection Facilities costs, in cash, letter of credit or A-/A3-rated parent guarantee, and is reduced as milestones are met.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Collateral requirements should be provided in sufficient amounts to fully cover Network Improvement Costs and Interconnection Facilities costs.\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customer pays interconnection facilities and network improvement costs through CIAC on a 'but for' basis.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"The Company will assess CIAC for Large Load Customer additions to recover all distribution and transmission costs necessary to interconnect the new Large Load Customer.\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Interconnection Facilities that solely benefit the customer are assigned to it through CIAC.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Large Load Customers are subject to a fee for Interconnection Facilities costs and Network Improvement Costs through CIAC.\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Network Improvement costs, including transmission, are allocated to the customer when they would not be needed but for its interconnection, even if others benefit.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"If a Network Improvement would not have been needed “but for” the interconnection of the Large Load Customer, then the costs of the upgrade will be allocated to that customer\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Model tariff includes interruptible service and onsite-generation options.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Large Load Customers bringing their own onsite generation and not using their full interconnection service request may be offered lower minimum demand charges and/or standby charges\"},\"btm_generation\":{\"status\":\"partial\",\"detail\":\"Customers with onsite generation may be offered lower minimum demand or standby charges at utility discretion; onsite generation offsetting grid demand in a curtailment counts as curtailment.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"A Large Load Customer bringing onsite generation and using that generation to offset demand for the Large Load Customer’s grid services during a curtailment event will be treated as having curtailed.\"},\"load_flexibility\":{\"status\":\"included\",\"detail\":\"Interruptible service contracts with mandatory capacity interruptions, penalties for failure to curtail, and removal to firm rate if the customer does not curtail.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Contract Service for Interruptible Power will be available to Large Load Customer customers based on the Company’s existing interruptible service tariff provisions.\"},\"price_premium\":{\"status\":\"included\",\"detail\":\"Annual universal service program contribution scaled by peak demand, from $250,000 (25-75 MW) to $1,000,000 (500 MW or more).\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Large Load Customers are to make an annual contribution to the Company’s universal service program based on the following peak demand schedule\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Customer pays full planning study costs; twice-yearly cluster 'Network Open Season'; studies due within six months or 50% of fee is refunded per 90-day delay.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"Interconnection Studies will be completed within six (6) months from the date that an application for interconnection study is accepted by the Company as complete.\"},\"load_ramp_period\":{\"status\":\"included\",\"detail\":\"Customer may designate a load ramp period of 3 to 5 years; the initial contract term starts after it ends.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"A Customer may designate a Load Ramp Period, which should be at or between three (3) years and five (5) years.\"},\"resize_reassign\":{\"status\":\"included\",\"detail\":\"After five years customers may cut capacity by up to 20% without fee on 48 months notice; utility will try to reassign released capacity to other large loads.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"the Company will use reasonable efforts, consistent with its obligations as a public utility, to mitigate the Exit Fee amount owed or paid by the Large Load Customer\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Exit fee is the greater of unrecovered network/interconnection costs or the remaining minimum charge on the reduced capacity, over an Exit Fee Period of 1 to 5 years; 48 months notice.\",\"source_url\":\"https://www.puc.pa.gov/pcdocs/1929842.pdf\",\"verbatim\":\"The Exit Fee will be calculated as the greater of (1) the difference between the cost of Network Improvements and Interconnection Facilities less the revenues received from the Large Load Customer\"}},\"additional_terms\":[{\"term\":\"Six-month study deadline\",\"detail\":\"Utilities must complete large-load interconnection studies within six months to improve development predictability.\",\"source_url\":\"https://www.puc.pa.gov/press-release/2026/puc-releases-final-order-establishing-first-of-its-kind-large-load-model-tariff-framework-05132026\"},{\"term\":\"Self-construction option\",\"detail\":\"Large load customers may self-construct certain infrastructure upgrades, subject to utility, safety, reliability, and regulatory standards.\",\"source_url\":\"https://www.puc.pa.gov/press-release/2026/puc-releases-final-order-establishing-first-of-its-kind-large-load-model-tariff-framework-05132026\"},{\"term\":\"Transparency requirement\",\"detail\":\"Utilities must maintain public-facing information on large-load interconnection requests and study status.\",\"source_url\":\"https://www.puc.pa.gov/press-release/2026/puc-releases-final-order-establishing-first-of-its-kind-large-load-model-tariff-framework-05132026\"}],\"legislation\":[],\"source_url\":\"https://www.puc.pa.gov/press-release/2026/puc-releases-final-order-establishing-first-of-its-kind-large-load-model-tariff-framework-05132026\",\"source_title\":\"PA PUC — Final Order establishing first-of-its-kind Large Load Model Tariff Framework\",\"resources\":[{\"url\":\"https://www.puc.pa.gov/press-release/2026/puc-acts-to-protect-ratepayers-guide-data-center-growth-with-new-large-load-tariff-framework-4-30-26\",\"title\":\"PA PUC — April 30, 2026 vote adopting the large load tariff framework\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"pge-oregon-schedule-96-large-load\",\"utility\":\"Portland General Electric (PGE)\",\"state\":\"OR\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Schedule 96 — Large Load Direct Access / large energy use facility rate class\",\"tariff_type\":\"Data center / large-load rate class\",\"status\":\"approved\",\"status_detail\":\"Approved by Oregon PUC Order No. 26-154 on May 7, 2026; revised tariffs filed June 3, schedules effective June 10, 2026.\",\"regulator\":\"Public Utility Commission of Oregon (OPUC)\",\"docket_number\":\"Order No. 26-154\",\"decision_date\":\"2026-05-07\",\"min_load_mw\":20.0,\"summary\":\"Oregon's first dedicated large-load rate class, requiring PGE data center and other large customers above 20 MW to cover 100% of distribution upgrades and pay minimum demand charges at 90% of contracted capacity, with contract terms that lengthen with project size — implementing 2025's HB 3546 so growth costs don't shift to residential ratepayers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Large load customer agreement required at 20 MW; Schedule 96 applies to data centers of 20 MW or more under HB 3546.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"Revise Rule I to lower minimum threshold for customers that require an LLCA to 20 MW.\"},\"customer_type\":{\"status\":\"included\",\"detail\":\"Schedule 96 is a class for data centers (NAICS 518210) of 20 MW or more, set up under Oregon HB 3546.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"a facility that uses or is able to use 20 megawatts or more and is primarily engaged in providing a service described under the 2022 North American Industry Classification System Code 518210\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"10 years at 20 MW, rising 1 year per 10 MW to 30 years at 220 MW or more.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"require a term of 10 years for a 20 MW load, with the term increasing by one year for each 10 MW increment in load up to a maximum of 30 years for a load 220 MW or greater\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Schedule 96 has transmission and related service, distribution, system usage and generation demand charges, at primary and subtransmission service levels.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"basic charge, transmission and related service charge, distribution charges, system usage charge, and generation demand charge\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Minimum generation demand and minimum transmission demand set at 90% of contracted capacity.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We adopt a MGD and MTD of90 percent\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Uniform credit requirements in the tariff (A- S&P / A3 Moody's debt rating), surety bonds allowed; plus a capacity allocation deposit of two years of minimum transmission demand, refundable 50% in year 2 and 50% in year 3 post-energization.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"charging a system capacity allocation deposit due at contract signing equal to two years of minimum transmission demand\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Transmission built to serve one customer is directly assigned to it; non-permanent transmission upgrades are 100% allocated to the benefiting customer; customers may pay CIAC up to 100% of distribution assets.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"when a transmission asset is built to serve a single customer, it is appropriate to directly assign the costs of that transmission asset to that customer\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Customers with an LLCA or MLA can contribute up to 100% CIAC for non-shared distribution assets; 100% of non-permanent transmission upgrade costs go to the beneficiary.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We find it appropriate to allocate 100 percent of the costs for any nonpermanent transmission facility upgrades to the customer benefiting from the nonpermanent upgrade.\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Single-customer transmission is directly assigned; customers 20 MW and above may fund CIAC up to 100% of generation and transmission investments.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"The record shows that direct assignment paired with the PGM can fairly allocate transmission costs.\"},\"dca_generation_capacity\":{\"status\":\"partial\",\"detail\":\"Customers 20 MW+ may pay CIAC up to 100% of generation and transmission investment; growth-related generation is allocated by the PGM to growth classes.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"generation investments will be considered growth-related when they are triggered by the need for incremental capacity or energy to reliably serve increased demand\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Special contracts for dedicated resources are considered case by case; direct access allowed with transition charges.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We will consider special contracts on a case-by-case.\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Customers can contract directly with PGE for dedicated resources via special contracts with a list of permissible resources; direct access also allowed with safeguards.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We accept the Coalition's proposed list of permissible resources for special contracts.\"},\"load_flexibility\":{\"status\":\"partial\",\"detail\":\"No flexible-load subclass or fast-track queue; flexibility is recognized as a credit in special contracts and as one element of a plan of service.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"we decline to create a subclass for flexible loads\"},\"price_premium\":{\"status\":\"included\",\"detail\":\"1 cent/kWh surcharge on Schedule 96 customers with allocated capacity of 100 MW or more, plus the maximum HB 3141 public-purpose contribution from all Schedule 96 customers.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We find that applying a surcharge of 1 cent per kWh to Schedule 96 customers with an Allocated System Capacity of 100 MW or greater\"},\"study_requirements\":{\"status\":\"partial\",\"detail\":\"Study costs are customer-paid; PGE gets a flat study fee for loads under 4 MW and study results expire after 60 days unless extended.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"charge a flat fee for all studies for customers under 4 MW\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Cost allocation uses a Planned Growth Method (PGM) that assigns growth-related generation and transmission costs to the classes driving growth, indefinitely.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We find the PGM will fairly allocate costs of growth to the classes of customers responsible for that growth and thus will prevent cost shifting\"},\"formulaic_backstop\":{\"status\":\"partial\",\"detail\":\"An 'EGM' mechanism was found generally reasonable for mitigating cost shift under the POWER Act; exit-fee revenue is applied to the departing class's revenue requirement.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"We find PGE's proposal for an EGM to be generally reasonable and consistent with the POWER Act's requirement\"},\"marginal_cost\":{\"status\":\"included\",\"detail\":\"Order updates PGE's marginal cost studies, including separate substation marginal costs by class, and adopts the PGM for growth-related cost allocation.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"calculate separate substation marginal costs by class to account for the significant differences in the way various customer classes use distribution infrastructure\"},\"resize_reassign\":{\"status\":\"included\",\"detail\":\"Exit fee may be refunded in whole or part, prorated, when another customer takes the exiting customer's capacity within three years.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"to allow refunds of the exit fee in whole or in part when another customer assumes the exiting customer's capacity within three years\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Exit fees apply to distribution costs below 20 MW and are extended to transmission and generation costs for loads of 20 MW and above; revenue goes to the departing customer's class.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"verbatim\":\"we find the Coalition's proposed exit fee for transmission and generation costs should be added for loads 20 MW and greater\"}},\"additional_terms\":[{\"term\":\"Rate impact\",\"detail\":\"Large-load data center rates rise ~29%, while residential rates fall ~1.3% and small-business rates ~3.7%.\",\"source_url\":\"https://www.utilitydive.com/news/oregon-puc-approves-pges-large-load-tariff-framework-for-data-centers/821361/\"},{\"term\":\"Economic development payments\",\"detail\":\"Loads over 100 MW pay a 1¢/kWh surcharge directed to offset residential customer costs and low-income energy burden.\",\"source_url\":\"https://www.oregon.gov/puc/news-events/Documents/PR-202609.pdf\"}],\"legislation\":[{\"policy_id\":\"or-hb3546-2025\",\"title\":\"Oregon HB 3546 (2025) — large energy use facilities\",\"url\":\"https://olis.oregonlegislature.gov/liz/2025R1/Measures/Overview/HB3546\",\"citation\":\"HB 3546, Chapter 323 (2025)\",\"status\":\"Enacted as Chapter 323 (2025), emergency clause; sunsets Jan 2, 2035\",\"summary\":\"Directs the Oregon PUC to create a new service classification for large energy use facilities that allocates serving costs to those facilities and mitigates risk to other customer classes — the basis for PGE's Schedule 96. Widely referred to as the POWER Act.\"}],\"source_url\":\"https://www.utilitydive.com/news/oregon-puc-approves-pges-large-load-tariff-framework-for-data-centers/821361/\",\"source_title\":\"Utility Dive — Oregon PUC approves PGE's large-load tariff framework for data centers\",\"resources\":[{\"url\":\"https://www.oregon.gov/puc/utilities/pages/large-load.aspx\",\"title\":\"Oregon PUC — Large Customer Demand / large-load rulemaking page\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"},{\"url\":\"https://www.oregon.gov/puc/news-events/Documents/PR-202609.pdf\",\"title\":\"Oregon PUC media release (PR-202609) — Oregon PUC Approves New Rate Structure to Protect Customers Amid Rapid Data Center Growth\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"xcel-colorado-large-load-tariff\",\"utility\":\"Public Service Company of Colorado (Xcel Energy)\",\"state\":\"CO\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Load Tariff\",\"tariff_type\":\"Large-load / data center tariff\",\"status\":\"proposed\",\"status_detail\":\"Advice letter (Proceeding 26AL-0137E, filed April 2, 2026) suspended and set for hearing by Decision C26-0280 (April 30, 2026). Decision C26-0430-I (June 26, 2026) set the procedural schedule with the evidentiary hearing on October 21, 22, 26, 27 and 28, 2026; Decision C26-0467 (July 10, 2026) scheduled remote public comment hearings for August 25 and October 20, 2026 and extended the suspension of the tariff sheets by an additional 130 days to January 8, 2027. Answer testimony was filed August 19, 2026 (Commission Staff, Western Resource Advocates, Google LLC, City of Boulder, United Power and others). As of September 25, 2026 the Colorado PUC's own key-proceedings and e-filings pages show no Commission decision on the merits — the case remains at the pre-hearing stage awaiting the late-October evidentiary hearing. As of October 29, 2026 the docket's most recent filings are hearing exhibits dated October 28 (revised Form ESA, CTT and Schedule TL), a United Power and PSCo settlement agreement (Hearing Exhibit 114, October 22) and a Trial Staff non-unanimous stipulation (Hearing Exhibit 1305, October 6); the docket status is still Suspended and no Commission decision on the merits is listed.\",\"regulator\":\"Colorado Public Utilities Commission (COPUC)\",\"docket_number\":\"26AL-0137E\",\"filed_date\":\"2026-04-02\",\"min_load_mw\":50.0,\"summary\":\"Proposed Xcel/Public Service Company of Colorado tariff requiring customers above 50 MW (and some 20–50 MW) to cover the transmission, substation, interconnection, and new-generation costs needed to serve them, with 15-year-plus contracts and financial security, so existing customers don't subsidize large new loads such as data centers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Proposed tariff applies to new customers or expansions of 50 MW or more; customers of 20-50 MW may also be subject to it.\",\"verbatim\":\"this tariff would apply to new customers or significant expansion of existing electric load of 50 megawatts (MW) or more.\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Proposed long-term commitments of typically 15 years or more.\",\"verbatim\":\"Large customers must make long-term contractual commitments — typically 15 years or more.\"},\"min_bill\":{\"status\":\"partial\",\"detail\":\"Proposed minimum monthly payment toward infrastructure built to serve the customer, even while load ramps up; no percentage stated in the release.\",\"verbatim\":\"Large customers contribute toward the cost of infrastructure constructed and available to serve them, even if load ramps up gradually.\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Proposed financial security requirements for projects that are delayed, scaled back or not completed; amount not stated in the release.\",\"verbatim\":\"Financial security requirements add extra protection if a project is delayed, scaled back or not completed.\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Large customers would pay for the transmission, substations, interconnection upgrades and new generation needed to serve them.\",\"verbatim\":\"large customers would pay for the power infrastructure needed to serve them.\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Customers cover interconnection upgrades and substations.\",\"verbatim\":\"This includes covering electric transmission, substations and interconnection upgrades as well as paying for new electric generation.\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Customers cover electric transmission needed to serve them.\",\"verbatim\":\"This includes covering electric transmission, substations and interconnection upgrades as well as paying for new electric generation.\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Customers pay for new electric generation procured to serve them.\",\"verbatim\":\"as well as paying for new electric generation\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Termination charges recover remaining costs of project-specific upgrades if a customer exits early.\",\"verbatim\":\"termination charges will recover remaining costs of project-specific upgrades built, avoiding stranded costs for other customers.\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Stated aim that existing customers do not subsidize large new customers; the release gives no revenue-versus-cost test (LBL describes Xcel's Schedule TL test separately).\",\"verbatim\":\"This ensures that existing customers are not paying for the needs of the large load customers.\"}},\"additional_terms\":[{\"term\":\"Service agreements required\",\"detail\":\"Large customers must execute Interconnection Agreements and Energy Service Agreements before receiving electric service.\",\"source_url\":\"https://newsroom.xcelenergy.com/news/xcel-energy-proposal-protects-customers-from-higher-bills-as-data-center-demand-grows\"},{\"term\":\"Demand context\",\"detail\":\"Public Service Company of Colorado projects large-load customers will make up two-thirds of new demand, needing ~950 MW of new generation over five years.\",\"source_url\":\"https://newsroom.xcelenergy.com/news/xcel-energy-proposal-protects-customers-from-higher-bills-as-data-center-demand-grows\"}],\"legislation\":[],\"source_url\":\"https://newsroom.xcelenergy.com/news/xcel-energy-proposal-protects-customers-from-higher-bills-as-data-center-demand-grows\",\"source_title\":\"Xcel Energy — Proposal protects customers from higher bills as data center demand grows\",\"resources\":[{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"},{\"url\":\"https://www.dora.state.co.us/pls/efi/EFI.Show_Docket?p_session_id=&p_docket_id=26AL-0137E\",\"title\":\"Colorado PUC E-Filings — Proceeding 26AL-0137E docket (filings and decisions)\"},{\"url\":\"https://www.dora.state.co.us/pls/efi/EFI_Search_UI.Show_Decision?p_dec=32982&p_session_id=\",\"title\":\"Colorado PUC Decision C26-0430-I — procedural schedule; evidentiary hearing Oct. 21–28, 2026\"},{\"url\":\"https://www.dora.state.co.us/pls/efi/EFI_Search_UI.Show_Decision?p_dec=33019&p_session_id=\",\"title\":\"Colorado PUC Decision C26-0467 — public comment hearings Aug. 25 and Oct. 20, 2026; suspension extended to Jan. 8, 2027\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"nv-microsoft-ratepayer-protection-tariff\",\"utility\":\"NV Energy (tariff proposed by Microsoft)\",\"state\":\"NV\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Ratepayer Protection Tariff (large-load cost allocation framework)\",\"tariff_type\":\"Ratepayer-protection / large-load cost allocation\",\"status\":\"proposed\",\"status_detail\":\"Filed May 2026 under PUCN Docket 20-08014 (reusing a docket opened August 2020) as a stakeholder proposal within an existing investigation, not yet an adopted tariff or rate class. Utility Dive (source_url) reports the commission is expected to move the matter through evaluation, scenario modeling and public comment before deciding whether to adopt the framework; other coverage (not independently re-verified this pass) has described public comment continuing through October 2026 with evidentiary hearings in January 2027 and a decision expected mid-2027. Re-checked 2026-09-25: no Commission decision on the Ratepayer Protection Tariff proposal has been found.\",\"regulator\":\"Public Utilities Commission of Nevada (PUCN)\",\"docket_number\":\"20-08014\",\"summary\":\"A statewide framework Microsoft proposed to Nevada regulators that would have NV Energy track the substations, generation, and transmission dedicated to each large-load customer and split costs into a customer-paid project share and a grid-benefit share — turning Microsoft's 'paying our way' pledge into an enforceable rate mechanism that shields residential and small-business ratepayers.\",\"parameters\":{\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Proposal splits project-specific infrastructure into a Customer Contributed Share paid by the large-load customer and a System Benefit Share that can be reviewed for rate base.\",\"verbatim\":\"The proposal splits project-specific infrastructure into a Customer Contributed Share, paid by the large-load customer, and a System Benefit Share\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"NV Energy would track substations and transmission facilities needed to serve the customer on a customer-specific asset schedule, paid by upfront contribution or ongoing facility payments.\",\"verbatim\":\"Large-load customers would pay for the project-specific share of those investments, either through an upfront contribution or ongoing facility payments.\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Customer-specific asset schedule covers generation facilities needed to serve the customer; customers may directly fund or finance new generation.\",\"verbatim\":\"NV Energy would identify and track substations, generation and transmission facilities needed to serve a large-load customer on a customer-specific asset schedule.\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Transmission facilities needed to serve the customer are tracked and charged to it, with customers able to fund or finance new transmission.\",\"verbatim\":\"allowing tech companies to directly fund or finance new generation and transmission infrastructure needed to serve their demand\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Final exit charge if the customer leaves before infrastructure payments are complete; amount not specified in the article.\",\"verbatim\":\"with a final exit charge if they leave before those payments are complete\"},\"load_ramp_period\":{\"status\":\"partial\",\"detail\":\"Electric service agreement would set a defined contract demand and load ramp; no ramp length given.\",\"verbatim\":\"Customers would enter into an electric service agreement with a defined contract demand and load ramp.\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Bring Your Own Power provision lets customers procure third-party generation.\",\"verbatim\":\"A “Bring Your Own Power” provision allows customers to procure generation from third-party providers\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Third-party generation procured by the customer has accredited capacity incorporated into utility planning assumptions.\",\"verbatim\":\"with accredited capacity incorporated into utility planning assumptions\"}},\"additional_terms\":[{\"term\":\"Expedited review\",\"detail\":\"Projects funded fully upfront may receive PUCN approval within 60 days where no system-benefit cost recovery is sought.\",\"source_url\":\"https://www.utilitydive.com/news/microsoft-seeks-nevada-tariff-to-shield-ratepayers-from-data-center-costs/822250/\"}],\"legislation\":[],\"source_url\":\"https://www.utilitydive.com/news/microsoft-seeks-nevada-tariff-to-shield-ratepayers-from-data-center-costs/822250/\",\"source_title\":\"Utility Dive — Microsoft seeks Nevada tariff to shield ratepayers from data center costs\",\"resources\":[{\"url\":\"https://www.datacenterdynamics.com/en/news/microsoft-proposes-ratepayer-protection-tariff-in-nevada/\",\"title\":\"DCD — Microsoft proposes ratepayer-protection tariff in Nevada\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"},{\"url\":\"https://puc-onbase.nv.gov/\",\"title\":\"PUCN Document Search portal — search type 'PUC - Public Search - Dockets', docket 20-08014\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"comed-il-large-load-deposit-2026\",\"utility\":\"Commonwealth Edison (ComEd)\",\"state\":\"IL\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large-Load Security Deposit Tariff (Docket P2025-0677)\",\"tariff_type\":\"Large-load deposit / interconnection surety rule\",\"status\":\"approved\",\"status_detail\":\"Illinois Commerce Commission order of March 19, 2026 in consolidated Dockets 25-0677/25-0679; compliance tariff sheets filed March 30 took effect March 31, 2026.\",\"regulator\":\"Illinois Commerce Commission (ICC)\",\"docket_number\":\"P2025-0677\",\"filed_date\":\"2025-01-01\",\"decision_date\":\"2026-03-19\",\"min_load_mw\":50.0,\"summary\":\"ICC approved ComEd's revised tariff requiring security deposits from large-load applicants requesting 50 MW or more: $1M for 50–200 MW, plus $500K per additional 100 MW above that. Deposits apply toward development costs on completed projects and are refunded (minus incurred costs) on cancellations. Simultaneously, ICC opened a separate investigation (staff report due ~late 2026) into additional consumer-protection mechanisms for data-center-driven distribution upgrades. First approved large-load surety tariff in Illinois.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to projects whose projected load ramp reaches 50 MW or more of Maximum Kilowatts Delivered within ten calendar years of requested service.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"equal to or greater than 50 MW at any time before December of the tenth (10th) calendar year after the requested date of service\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Deposit of $1,000,000 plus $500,000 per additional whole 100 MW above 200 MW; amount over $2,000,000 must be backed by an Acceptable Letter of Credit; refunded when service starts.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"the sum of $1,000,000 plus $500,000 for each additional whole 100 MW of MKD above 200 MW\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Customers provide security for ComEd's analysis and engineering costs; ComEd may combine requests into a Cluster Study of transmission and distribution impacts.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"A Large Demand Project Applicant or Customer is required to provide a security for the Company’s analysis and engineering costs.\"},\"min_contract_duration\":{\"status\":\"partial\",\"detail\":\"No retail contract term; a Transmission Security Agreement guarantees transmission payments for 10 years after service begins.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"will not for a period of ten (10) years after the commencement of service fall below the annual payment that would be made by a customer meeting the load ramp submitted to ComEd\"},\"min_bill\":{\"status\":\"partial\",\"detail\":\"Annual transmission service payments are guaranteed at no less than the amount a customer meeting its submitted load ramp would pay, for 10 years.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"guarantee that its annual payments for transmission service, calculated in accordance with Attachment H-13 of the PJM Open Access Transmission Tariff (OATT)\"},\"load_ramp_period\":{\"status\":\"partial\",\"detail\":\"Applicant submits a projected monthly load ramp, used to size the deposit and the transmission guarantee; no maximum ramp length set.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"“load ramp” and “projected load ramp” both mean the anticipated monthly request of new or increased electrical usage in MW\"},\"explicit_load_forecast\":{\"status\":\"included\",\"detail\":\"Applicants must provide a projected monthly load ramp with the application.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"a deposit calculated based on the MKD included in the load ramp provided by the Application or Customer\"},\"load_forecast_requirement\":{\"status\":\"included\",\"detail\":\"Applicants must provide a projected monthly load ramp with the application.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"a deposit calculated based on the MKD included in the load ramp provided by the Application or Customer\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Transmission revenue shortfalls from a large load are recovered from it under the TSA and credited to other transmission customers in the ComEd zone.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"If there is a revenue shortfall from the LDPAC in any year, the delta will be recovered under the TSA with that LDPAC\"},\"formulaic_backstop\":{\"status\":\"included\",\"detail\":\"Annual shortfall between guaranteed and actual transmission payments is collected and credited to the transmission revenue requirement of other customers.\",\"source_url\":\"https://icc.illinois.gov/downloads/public/filing/4/397281.pdf\",\"verbatim\":\"credited to the transmission revenue requirement borne by transmission customers in the ComEd zone\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://capitolnewsillinois.com/news/regulators-ok-comeds-plan-to-increase-deposit-costs-for-large-load-projects-like-data-centers/\",\"source_title\":\"Capitol News Illinois — Regulators OK ComEd's plan to increase deposit costs for large-load projects like data centers\",\"resources\":[{\"url\":\"https://capitolnewsillinois.com/news/regulators-ok-comeds-plan-to-increase-deposit-costs-for-large-load-projects-like-data-centers/\",\"title\":\"Capitol News Illinois — ComEd large-load deposit tariff approved (March 2026)\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"aps-arizona-large-load-rate-case-2025\",\"utility\":\"Arizona Public Service (APS)\",\"state\":\"AZ\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large-Load Cost-of-Service Tariff (ACC Rate Case E-01345A-25-0105)\",\"tariff_type\":\"Large-load cost-of-service rate case\",\"status\":\"proposed\",\"status_detail\":\"Evidentiary hearing before an administrative law judge began May 18, 2026 with more than 30 intervenors and concluded on July 7, 2026 (per the ACC). The ALJ's Recommended Opinion and Order 'may take months'; the ACC expects the ALJ's Recommended Opinion and Order by late November 2026 and the Commission must vote by December 31, 2026; APS says a final ACC decision is expected later in 2026, with requested rates effective no earlier than July 8, 2026 — in practice early 2027. As of September 25, 2026 the ACC's news page lists no Recommended Opinion and Order or open-meeting item on the case.\",\"regulator\":\"Arizona Corporation Commission (ACC)\",\"docket_number\":\"E-01345A-25-0105\",\"filed_date\":\"2025-06-01\",\"summary\":\"APS proposed a 45% rate increase for extra-large energy users (data centers) versus ~15% for households, explicitly structuring rates so data centers pay their own cost of service rather than shifting grid-upgrade costs onto residential ratepayers. Includes formula rates tying infrastructure costs directly to the large-load customers who cause them. The ACC hosted a large-load / data-center workshop April 20, 2026 to gather stakeholder input; final order expected late 2026.\",\"parameters\":{\"customer_type\":{\"status\":\"included\",\"detail\":\"The Extra High Load Factor rate applies to large load users such as manufacturers and data centers; APS proposed updating its eligibility.\",\"source_url\":\"https://azcc.gov/news/home/2026/07/10/what-s-next-in-the-aps-rate-case\",\"verbatim\":\"Extra High Load Factor (which applies to large load users, such as manufacturing companies and data centers)\"},\"min_contract_duration\":{\"status\":\"partial\",\"detail\":\"APS says data center customers would sign long-term contracts covering infrastructure costs; no term length stated in the sources read.\",\"verbatim\":\"Data center customers would sign long-term contracts covering the costs to build and maintain infrastructure over the long-term\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"APS proposes future infrastructure needs be paid for by the data center customers who would use it.\",\"verbatim\":\"future infrastructure needs are paid for by the data center customers who would use it, not by existing residential or business customers\"},\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"APS proposed a bring-your-own-power policy to workshop participants at the ACC.\",\"source_url\":\"https://www.azcc.gov/news/home/2026/04/20/acc-large-load-data-center-workshop-highlights\",\"verbatim\":\"a bring your own power policy that would directly assign the costs to produce new electricity generation\"},\"customer_led_procurement\":{\"status\":\"partial\",\"detail\":\"Proposed bring-your-own-power policy directly assigns the cost of new generation to the customer.\",\"source_url\":\"https://www.azcc.gov/news/home/2026/04/20/acc-large-load-data-center-workshop-highlights\",\"verbatim\":\"a bring your own power policy that would directly assign the costs to produce new electricity generation\"},\"dca_generation_capacity\":{\"status\":\"partial\",\"detail\":\"Proposed policy assigns the cost of new generation to the data center customer.\",\"source_url\":\"https://www.azcc.gov/news/home/2026/04/20/acc-large-load-data-center-workshop-highlights\",\"verbatim\":\"a bring your own power policy that would directly assign the costs to produce new electricity generation\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Proposed formula rates test annually whether rates recover cost to serve each class and adjust them so residential customers do not bear data center growth costs.\",\"verbatim\":\"This annual process would verify that residential and other business customers are not receiving cost increases associated with data center growth.\"},\"formulaic_backstop\":{\"status\":\"included\",\"detail\":\"Formula Rate Adjustment Mechanism proposed: APS checks cost to serve each year and assigns increases caused by extra-large customers to them.\",\"verbatim\":\"If extra-large customers like data centers cause costs to rise, those costs will be assigned to them.\"},\"price_premium\":{\"status\":\"partial\",\"detail\":\"APS proposed a rate increase of more than 45% for extra-large users so they cover their cost of service.\",\"verbatim\":\"we proposed a 45% rate increase for these extra-large energy users\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://www.aps.com/en/Utility/Company-wide-Events-and-Messages/Data_Centers_How_Were_Protecting_Customers_While_Planning-for_Big_Energy_Needs\",\"source_title\":\"APS — Data Centers: How We're Protecting Customers While Planning for Big Energy Needs\",\"resources\":[{\"url\":\"https://www.aps.com/en/Utility/Company-wide-Events-and-Messages/Data_Centers_How_Were_Protecting_Customers_While_Planning-for_Big_Energy_Needs\",\"title\":\"APS — Data Center customer protection explainer\"},{\"url\":\"https://www.azcc.gov/news/home/2026/04/20/acc-large-load-data-center-workshop-highlights\",\"title\":\"ACC — Large-Load / Data Center Workshop Highlights (April 20, 2026)\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"},{\"url\":\"https://www.aps.com/en/About/Our-Company/Newsroom/Articles/APS-Rate-Case-Hearing-Concludes-Process-Moves-to-Next-Phase\",\"title\":\"APS — Rate Case Hearing Concludes; Process Moves to Next Phase (July 10, 2026)\"},{\"url\":\"https://azcc.gov/news/home/2026/07/10/what-s-next-in-the-aps-rate-case\",\"title\":\"ACC — What's Next in the APS Rate Case? (July 10, 2026)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"duke-nc-large-load-rate-case-2025\",\"utility\":\"Duke Energy Carolinas / Duke Energy Progress\",\"state\":\"NC\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large-Load Customer Class Proposal (NCUC Rate Case E-7, Sub 1329)\",\"tariff_type\":\"Large-load rate case — cost-of-service and class design\",\"status\":\"proposed\",\"status_detail\":\"A Second Amended Comprehensive Revenue Requirement Agreement and Stipulation of Settlement (Duke Energy Carolinas, NCUC Public Staff, industrial/customer groups, and Microsoft Corporation) was filed July 17, 2026 and amended July 20, 2026 (Andale, LLC later added as a stipulating party), committing Duke and Public Staff to submit a dedicated large-load tariff by the end of September 2026. If approved, residential customers using 1,000 kWh/month would see bills rise $17.22/month (from $144.98 to $162.20) beginning January 1, 2027. As of September 25, 2026 no NCUC order on the settlement has been located (the Commission's docket system blocks automated retrieval). On September 14, 2026 Attorney General Jeff Jackson — who declined to sign the settlement — filed a proposal in Duke's rate-case dockets for a new rate class for data centers and other large-load customers, part of the process the Commission opened after he requested a separate large-load proceeding (NCDOJ release). On October 7, 2026 WUNC and Blue Ridge Public Radio reported that Duke Energy had reached an agreement with data center operators on a large-load tariff; the Utilities Commission must approve some version before it takes effect, and no hearing or decision date had been announced as of October 18, 2026. The Southern Environmental Law Center reports the large-load settlement was first made public October 6, 2026; no NCUC order on it had been found as of November 16, 2026. On Oct 6, 2026, Duke, the Public Staff, Amazon, Google, Microsoft and others filed a Large Load Tariff settlement (Dockets E-7 Sub 1329 / E-2 Sub 1380) for Duke Energy Carolinas and Duke Energy Progress, to take effect Jan 1, 2027; it awaits NCUC approval.\",\"regulator\":\"North Carolina Utilities Commission (NCUC)\",\"docket_number\":\"E-7, Sub 1329\",\"filed_date\":\"2025-11-20\",\"min_load_mw\":50.0,\"summary\":\"Duke Energy's 2025 rate case is the arena for a major fight over large-load tariff design in North Carolina. The NC Attorney General, NCUC Public Staff, and advocacy groups independently proposed a new large-load customer class (50+ MW) with special rules and rates for data centers. Duke Energy Carolinas reached a Second Amended Settlement Stipulation (July 17/20, 2026) with the Public Staff, other parties, and Microsoft Corporation to develop the large-load tariff via a fast-track process, committing to file it by the end of September 2026; per testimony filed in late June 2026, Duke proposed that data centers and other large loads above 50 MW pay at least 75% of their contracted capacity for 10 to 15 years, regardless of actual usage. Duke has approximately 6 GW of data center demand in its interconnection queue. NCUC approval of the settlement is still pending.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies at 50 MW contract demand with 80% expected load factor, or at 150 MW contract demand at any load factor, for agreements executed on or after June 1, 2026.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"a total contract demand of 50 MW or more and an expected 12-month rolling average load factor of 80% of more, or (b) a total contract demand of 150 MW or more and any load factor\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Customers at one premises or multiple premises within one mile of each other are treated together.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"served at either a single premises, or at multiple premises within one mile of each other\"},\"load_factor_threshold\":{\"status\":\"included\",\"detail\":\"Expected 12-month rolling average load factor of 80% or more for the 50 MW tier; measured on forecast at full operation, with move-in if actual use later meets it.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"expected load factor shall be determined using the customer’s forecasted twelve (12) month rolling average at full operation\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Below 100 MW: greater of 10 years or 5 years plus load ramp; 100 MW or more: greater of 15 years or 10 years plus load ramp; then one-year auto-extensions with 24 months notice.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The minimum initial contract term for ESAs of 100 MW or more will be the greater of (a) 15 years and (b) 10 years plus the load ramp period.\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Customers are served under Schedule HLF, whose demand charges are subject to a 75% billing demand floor.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"Billing demand will not be less than 75% of contract demand for all demand charges in Schedule HLF.\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Billing demand at least 75% of contract demand for all HLF demand charges, from when contract demand takes effect.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"Billing demand will not be less than 75% of contract demand for all demand charges in Schedule HLF.\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Security equal to early-termination liquidated damages in cash, letter of credit or parent guarantee; separate letter of credit for the cost of transmission network upgrades.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The customer must provide security equal to the applicable liquidated damages for early termination in the form of cash, letter of credit or parent guarantee\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Dedicated facilities funded in advance as CIAC; transmission network upgrades secured by letter of credit, with a direct-assignment methodology due within 12 months of approval.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The customer will provide advanced funds equal to the estimated total cost of Dedicated Facilities as a contribution in aid of construction (CIAC)\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Customer pays estimated dedicated facilities cost as CIAC within 60 days of the letter agreement and covers actual overruns.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The customer will further provide all necessary additional funds to cover the actual cost of such Dedicated Facilities\"},\"dca_network_transmission\":{\"status\":\"partial\",\"detail\":\"Customer posts a letter of credit for estimated network upgrade costs; any portion later direct-assigned by an approved method is paid as CIAC.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The customer will provide a deposit in the form of a letter of credit equal to the estimated total cost of transmission network upgrades necessary to serve the customer load\"},\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"Reliability provision lets an ESA use alternative Commission-approved options that accelerate capacity resources; no customer-led procurement program.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"Alternative Commission-approved options that accelerate capacity resources on the utility system during the integration of the customer’s full contract demand\"},\"load_flexibility\":{\"status\":\"included\",\"detail\":\"Each ESA includes interruptibility of 95% of load for up to 50 hours/year or 50% for up to 100 hours/year during the ramp period plus one year; uncompensated.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"Interruptibility of 95% of contract load for up to 50 hours per year for the load ramp period plus one year of service\"},\"load_ramp_period\":{\"status\":\"partial\",\"detail\":\"Contract term is the greater of a fixed term or a shorter fixed term plus the load ramp period; no maximum ramp length set in the tariff.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"The minimum initial contract term for ESAs below 100 MW will be the greater of (a) 10 years and (b) 5 years plus the load ramp period.\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Liquidated damages: 100% of minimum billing demand charges during notice period, NPV of remaining extra facilities charges, plus 25% of remaining minimum billing demand charges.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"plus (3) 25% of remaining minimum billing demand charges at the customer’s annual contract demand under the remaining term of the contract\"},\"resize_reassign\":{\"status\":\"included\",\"detail\":\"After the 6th anniversary a customer may cut contract demand once by up to 20% (max 200 MW) without liquidated damages; notice of 24 to 48 months otherwise.\",\"source_url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"verbatim\":\"the customer may provide notice to reduce contract demand by up to 20% but no greater than 200 MW, one time, without incurring liquidated damages\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://www.duke-energy.com/home/billing/dec-nc-rate-case\",\"source_title\":\"Duke Energy — 2025 Duke Energy Carolinas and Duke Energy Progress Rate Request\",\"resources\":[{\"url\":\"https://blogs.edf.org/climate411/2026/07/23/duke-energy-settlement-beginning-north-carolina-data-center-energy-policy/\",\"title\":\"EDF Climate 411 — The Duke Energy settlement is just the beginning for North Carolina's data center energy policy\"},{\"url\":\"https://www.axios.com/local/raleigh/2026/07/20/duke-energy-and-state-reach-agreement-on-lower-rate-increase-request\",\"title\":\"Axios Raleigh — Duke Energy and state reach agreement on lower rate increase request\"},{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2025-01/electricity_rate_designs_for_large_loads_evolving_practices_and_opportunities_final.pdf\",\"title\":\"DOE/Berkeley Lab — Electricity Rate Designs for Large Loads (Jan 2025)\"},{\"url\":\"https://ncdoj.gov/attorney-general-jeff-jackson-proposes-framework-to-ensure-data-centers-pay-their-fair-share-for-energy-costs/\",\"title\":\"NCDOJ — Attorney General Jackson proposes framework to ensure data centers pay their fair share (Sept. 14, 2026)\"},{\"url\":\"https://www.selc.org/?p=44685\",\"title\":\"SELC — on the Duke Energy large-load settlement\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"virginia-data-center-electricity-consumption-tax\",\"utility\":\"Virginia electric utilities and self-supplying data centers (statewide, via state budget)\",\"state\":\"VA\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Data Center Electricity Consumption Tax (HB30, Item 3-5.24)\",\"tariff_type\":\"Data center electricity consumption tax (state budget-enacted, not a utility-filed rate design)\",\"status\":\"approved\",\"status_detail\":\"Enacted as part of the FY2026–2028 state budget, signed by Governor Abigail Spanberger; took effect July 1, 2026. Distinct from the Dominion GS-5 rate class (see dominion-virginia-gs5-rate-class) — this is a statewide tax collected alongside utility bills, not an SCC-approved utility rate design.\",\"regulator\":\"Virginia Department of Taxation (State Corporation Commission administers collection/remittance)\",\"docket_number\":\"HB30, Item 3-5.24\",\"summary\":\"Virginia's FY2026–2028 state budget imposes a $0.011/kWh consumption tax on all electricity used by data centers statewide — utility-supplied, from a competitive retail provider, or self-generated on-site — effective July 1, 2026 and sunsetting July 1, 2028, with annual revenue above $600 million refunded pro rata to operators.\",\"parameters\":{\"customer_type\":{\"status\":\"included\",\"detail\":\"Tax applies to data center operators; 'data center' is defined by primary use, excluding facilities whose primary function is internet access or communication service.\",\"verbatim\":\"“Data center” does not include a facility whose primary function is to facilitate the provision of internet access service, a communication service as defined in § 58.1-647\"},\"min_demand_threshold\":{\"status\":\"partial\",\"detail\":\"Definition of data center requires electrical equipment managing at least one megawatt of capacity; no other size floor.\",\"verbatim\":\"equipment used for the transformation, transmission, distribution, or management of at least one megawatt of capacity of electrical power and cooling\"},\"price_premium\":{\"status\":\"partial\",\"detail\":\"Tax of $0.011/kWh on all data center electricity consumed, July 1, 2026 to July 1, 2028; general fund receives up to $600M/yr, excess is refunded pro rata to operators. It is a state tax, not a utility rate.\",\"verbatim\":\"an electricity consumption tax at the rate of $0.011/kWh of all electricity consumed at each data center per month\"}},\"additional_terms\":[{\"term\":\"Consumption tax rate\",\"detail\":\"$0.011 per kWh on all electricity consumed at a data center per month; no minimum-load exemption documented — applies broadly, unlike the GS-5 rate class's 25 MW threshold.\"},{\"term\":\"Revenue cap + refund\",\"detail\":\"Annual collections above $600 million (net of SCC administrative costs) go to a non-reverting special fund and are refunded pro rata to data center operators, rather than kept by the general fund.\"},{\"term\":\"Sunset\",\"detail\":\"The tax expires July 1, 2028 absent legislative extension.\"}],\"legislation\":[{\"title\":\"Virginia HB30 (2026 budget), Item 3-5.24\",\"url\":\"https://budget.lis.virginia.gov/amendment/2026/2/HB30/Introduced/CR/3-5.24/1c\",\"citation\":\"HB30, Item 3-5.24\",\"status\":\"Enacted, effective 2026-07-01\",\"summary\":\"The budget item that creates the consumption tax directly.\"}],\"source_url\":\"https://budget.lis.virginia.gov/amendment/2026/2/HB30/Introduced/CR/3-5.24/1c\",\"source_title\":\"Virginia General Assembly — HB30 Conference Report, Item 3-5.24 (Data Center Electricity Consumption Tax)\",\"resources\":[{\"url\":\"https://www.datacenterknowledge.com/regulations/virginia-approves-first-ever-data-center-power-tax\",\"title\":\"Data Center Knowledge — Virginia Approves First-Ever Data Center Power Tax\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"xcel-minnesota-large-load-tariff\",\"utility\":\"Xcel Energy (Northern States Power — Minnesota)\",\"state\":\"MN\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Load Tariff\",\"tariff_type\":\"Data center / large-load tariff\",\"status\":\"approved\",\"status_detail\":\"Approved May 15, 2026; the Commission also directed Xcel to file a separate clean energy and capacity tariff by December 1, 2026. The written order creating the Very Large Customer class is dated June 12, 2026.\",\"regulator\":\"Minnesota Public Utilities Commission (PUC)\",\"decision_date\":\"2026-05-15\",\"min_load_mw\":100.0,\"summary\":\"Creates a dedicated rate class for very large new customers (100 MW and up, aimed at data centers) with 15-year minimum contracts and an 80% demand-charge obligation on early exit, so infrastructure built for large loads is paid for by them rather than shifted to other customers in future rate cases.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Very large customers are new loads of 100 MW or more, plus new 20-100 MW loads that are 'system intensive'.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"The Commission defined “very large customers” for purposes of Xcel’s tariffs as new loads sized 100 megawatts (MW) or greater.\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"15-year default contract term.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"The Commission approved Xcel’s proposed 15-year default contract term and 24 month exit notice period.\"},\"min_bill\":{\"status\":\"included\",\"detail\":\"Minimum bill set at 80% of contracted capacity, raised from Xcel's proposal.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"the Commission increased the minimum bill and exit fee proposed by Xcel to 80% of the customer’s contracted capacity\"},\"min_billing_demand\":{\"status\":\"partial\",\"detail\":\"Minimum bill is tied to 80% of contracted capacity; the release does not describe it as a billing-demand floor.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"the Commission increased the minimum bill and exit fee proposed by Xcel to 80% of the customer’s contracted capacity\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"All transmission and distribution upgrades needed to serve very large customers are paid by them as CIAC.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"All transmission and distribution upgrades needed to serve very large customers must be paid directly by those customers through Contributions in Aid of Construction (CIAC).\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Distribution upgrades needed to serve the customer are CIAC.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"All transmission and distribution upgrades needed to serve very large customers must be paid directly by those customers\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Transmission upgrades needed to serve the customer are CIAC.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"All transmission and distribution upgrades needed to serve very large customers must be paid directly by those customers\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Exit fee set at 80% of contracted capacity with a 24-month exit notice period.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"the Commission increased the minimum bill and exit fee proposed by Xcel to 80% of the customer’s contracted capacity\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Xcel must file an Incremental Cost Test showing very large customers cover system, generation and transmission costs they create; Commission added OAG-recommended filing requirements.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"The Commission approved Xcel’s Incremental Cost Test (ICT) but adopted new requirements recommended by the OAG\"},\"marginal_cost\":{\"status\":\"included\",\"detail\":\"Incremental Cost Test compares costs of system, generation and transmission against revenue from the very large customer class.\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"ensure very large customers fully cover all of the system, generation, and transmission costs they create\"},\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"For each new customer Xcel must demonstrate supply meets Minnesota renewable and carbon-free benchmarks; a separate clean energy and capacity tariff is due Dec 1, 2026 (per ELPC).\",\"source_url\":\"https://content.govdelivery.com/accounts/MNPUBUC/bulletins/417d139\",\"verbatim\":\"For each new customer, Xcel must demonstrate that the electricity provided will meet Minnesota’s renewable and carbon free energy benchmarks\"}},\"additional_terms\":[],\"legislation\":[],\"source_url\":\"https://fresh-energy.org/regulatory-update-commission-approves-xcel-energys-large-load-tariff\",\"source_title\":\"Fresh Energy — Commission approves Xcel Energy's large load tariff\",\"resources\":[{\"url\":\"https://elpc.org/news/final-order-encourages-affordable-clean-energy-for-minnesotans/\",\"title\":\"ELPC — Final order encourages affordable, clean energy for Minnesotans\"},{\"url\":\"https://newsroom.xcelenergy.com/news/xcel-energy-proposal-protects-customers-from-higher-bills-as-data-center-demand-grows\",\"title\":\"Xcel Energy — proposal protects customers from higher bills as data center demand grows\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"northwestern-energy-mt-2026-03\",\"utility\":\"NorthWestern Energy\",\"state\":\"MT\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large New Load Service Tariff Rule, Rule No. 24 (\\\"LNL Rule\\\")\",\"tariff_type\":\"Data center / large-load tariff\",\"status\":\"proposed\",\"status_detail\":\"Application pending before the Montana PSC as of this pass (Docket No. 2026.04.023). A coalition of ratepayer, environmental, and Indigenous-led groups (Big Sky 55+, Butte Watchdogs for Social and Environmental Justice, Climate Smart Missoula, Helena Interfaith Climate Advocates, Honor the Earth, Montana Environmental Information Center, Montana Public Interest Research Group, and NW Energy Coalition), represented by Earthjustice, intervened June 15, 2026 seeking a mandatory ratepayer-protective tariff and a separate data-center customer class rather than NorthWestern's proposed rule. NorthWestern opposes the intervenors' motion to clarify/expand the docket's scope; the Montana Department of Environmental Quality, Missoula County, the Large Customer Group, and the Northwest & Intermountain Power Producers Coalition had not taken a position as of the intervenors' July 9, 2026 filing.\",\"regulator\":\"Montana Public Service Commission (PSC)\",\"docket_number\":\"2026.04.023\",\"filed_date\":\"2026-03-31\",\"min_load_mw\":5.0,\"summary\":\"NorthWestern Energy's proposed Large New Load Service Tariff Rule (Rule No. 24) would set requirements and contract terms — minimum service commitments, billing, collateral/performance assurance, and termination-cost provisions — for serving new or expanded loads of 5 MW or more, including data centers; loads of 50 MW or more require Montana PSC review before service begins.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Framework covers new or expanded customers with expected load of 5 MW or more; executed ESAs of 50 MW or more must be filed for PSC approval.\",\"verbatim\":\"onboarding new or expanded customers with an expected load of 5 megawatts or more\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Minimum service commitment periods, longer for loads of 50 MW or more; lengths not stated in the release.\",\"verbatim\":\"Minimum service commitment periods, including longer minimum terms for customers with very large loads (50 megawatts or greater)\"},\"min_billing_demand\":{\"status\":\"included\",\"detail\":\"Minimum demand and minimum energy billing requirements in each ESA; percentages not stated in the release.\",\"verbatim\":\"Minimum demand and minimum energy billing requirements to ensure these customers pay for the capacity and energy needed to serve them\"},\"min_bill\":{\"status\":\"partial\",\"detail\":\"Minimum energy billing requirement in ESAs; amount not stated in the release.\",\"verbatim\":\"Minimum demand and minimum energy billing requirements to ensure these customers pay for the capacity and energy needed to serve them\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Performance assurance and collateral requirements secure payment and performance; amounts set in the tariff/ESA.\",\"verbatim\":\"Performance assurance and collateral requirements to secure customer payment and performance obligations\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Termination cost provisions apply if a customer reduces load or terminates before the end of the term.\",\"verbatim\":\"Termination cost provisions designed to address costs remaining if a customer reduces load or terminates service before the end of the contract term\"},\"resize_reassign\":{\"status\":\"partial\",\"detail\":\"Termination costs also apply when a customer reduces load; reassignment is not described in the release.\",\"verbatim\":\"costs remaining if a customer reduces load or terminates service before the end of the contract term\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Prospective customers sign a development agreement and fund studies of system impacts, infrastructure needs and feasibility before the ESA.\",\"verbatim\":\"prospective large new load customers first enter into a development agreement and fund studies to evaluate system impacts, infrastructure needs, and service feasibility\"},\"hold_harmless\":{\"status\":\"partial\",\"detail\":\"Stated purpose is that existing customers do not subsidize large new loads; no test or backstop is described in the release.\",\"verbatim\":\"existing customers do not subsidize these large new load customers\"}},\"additional_terms\":[{\"term\":\"Confidentiality of data-center agreements\",\"detail\":\"A related PSC protective order (Dkt. No. 2025.11.084, granted Dec. 2025) shields NorthWestern's letters of intent with three prospective data-center developers (up to 1,400 MW combined) from public disclosure; the same intervenor coalition is separately challenging that confidentiality order, arguing Montanans have a right to know and participate in decisions affecting their utility bills.\",\"source_url\":\"https://earthjustice.org/press/2026/groups-challenge-montana-psc-order-that-shields-data-center-plans-from-public-view\"}],\"legislation\":[],\"source_url\":\"https://northwesternenergy.com/about-us/our-company/2026/04/01/northwestern-energy-submits-large-new-load-tariff-proposal-to-strengthen-customer-safeguards-and-support-montana-s-energy-future-and-economic-growth\",\"source_title\":\"NorthWestern Energy — NorthWestern Energy Submits Large New Load Tariff Proposal to Strengthen Customer Safeguards and Support Montana's Energy Future and Economic Growth\",\"resources\":[{\"url\":\"https://dailymontanan.com/2026/04/02/northwestern-energy-files-data-center-tariff-proposal/\",\"title\":\"Daily Montanan — NorthWestern Energy files data center tariff proposal\"},{\"url\":\"https://earthjustice.org/press/2026/groups-seek-intervention-in-northwestern-energy-data-center-tariff-proceeding\",\"title\":\"Earthjustice — Groups Seek Intervention in NorthWestern Energy Data Center Tariff Proceeding\"},{\"url\":\"https://earthjustice.org/wp-content/uploads/2026/07/2026-07-09-motion-to-clarify-scope-and-brief-in-support.pdf\",\"title\":\"Earthjustice — Intervenors' Motion to Clarify the Scope and Brief in Support, Dkt. No. 2026.04.023 (PDF)\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"iid-ca-large-load-tariff-2026\",\"utility\":\"Imperial Irrigation District (IID)\",\"state\":\"CA\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Large Load Tariff\",\"tariff_type\":\"Data center / large-load tariff (publicly owned utility)\",\"status\":\"approved\",\"status_detail\":\"Approved unanimously by the IID Board of Directors on September 15, 2026 after a 30-day public review (proposed May 15, 2026) that drew 243 comments and produced revisions. IID is a publicly owned irrigation district and electric utility whose rates are set by its elected board rather than the CPUC; no docket number exists. Effective date not stated in coverage.\",\"regulator\":\"Imperial Irrigation District Board of Directors (publicly owned utility; not CPUC rate-regulated)\",\"decision_date\":\"2026-09-15\",\"min_load_mw\":20.0,\"summary\":\"IID's Large Load Tariff sets how the district evaluates and serves customers requesting at least 20 MW of demand at an 80% minimum load factor — including data centers — making them 'responsible for the costs and financial risks associated with serving their projects, including needed infrastructure and power supply' rather than existing ratepayers, with a formal process to determine whether IID can reliably serve a proposed load and what system improvements are required. Coverage also describes 15-year service commitments, cash deposits, minimum monthly charges of at least 85% of contracted usage, customer-funded renewable procurement, and first-in-line curtailment of large users when demand peaks.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Applies to customers requesting at least 20 MW of electric demand (all large customers, not only data centers).\",\"source_url\":\"https://www.publicpower.org/periodical/article/imperial-irrigation-district-board-unanimously-approves-large-load-tariff\",\"verbatim\":\"The tariff applies to customers requesting at least 20 megawatts of electric demand and meeting an 80 percent minimum load factor\"},\"load_factor_threshold\":{\"status\":\"included\",\"detail\":\"Customers must meet an 80% minimum load factor.\",\"source_url\":\"https://www.publicpower.org/periodical/article/imperial-irrigation-district-board-unanimously-approves-large-load-tariff\",\"verbatim\":\"meeting an 80 percent minimum load factor\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Customers commit to 15 years of energy service.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"commit to 15 years of energy service\"},\"min_bill\":{\"status\":\"included\",\"detail\":\"Minimum monthly charge of at least 85% of the customer's contracted energy usage; no dollar figure is set.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"the fees would be set at least 85% of the customer’s contracted energy usage\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Customers must provide a cash deposit; amount not stated.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"providing a cash deposit and covering the price of purchasing renewable energy\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Customers bear the costs and financial risks of serving their projects, including infrastructure and power supply.\",\"source_url\":\"https://www.publicpower.org/periodical/article/imperial-irrigation-district-board-unanimously-approves-large-load-tariff\",\"verbatim\":\"large-load customers will be responsible for the costs and financial risks associated with serving their projects, including needed infrastructure and power supply\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Customers cover substations and distribution facilities IID needs to serve them.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"including substations, distribution facilities and transmission lines\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Customers cover transmission lines IID needs to deliver electricity to them.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"including substations, distribution facilities and transmission lines\"},\"dca_generation_capacity\":{\"status\":\"partial\",\"detail\":\"Customer is responsible for power supply costs and for the price of renewable energy needed to meet state standards.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"covering the price of purchasing renewable energy to keep up with state environmental standards\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"Formal process determines whether IID can reliably serve a proposed large load and what system improvements are required.\",\"source_url\":\"https://www.publicpower.org/periodical/article/imperial-irrigation-district-board-unanimously-approves-large-load-tariff\",\"verbatim\":\"The tariff also establishes a formal process for determining whether IID can reliably serve a proposed large load and what system improvements may be required.\"},\"customer_resource_procurement\":{\"status\":\"partial\",\"detail\":\"Tariff includes a curtailment-first provision for large users; no customer-procured resource option is described.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"the pricing rules give IID the right to cut off power to those large users first\"},\"load_flexibility\":{\"status\":\"partial\",\"detail\":\"IID may curtail large-load customers first when demand surges; no compensation or program terms described.\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"verbatim\":\"the pricing rules give IID the right to cut off power to those large users first\"}},\"additional_terms\":[{\"term\":\"Curtailment priority\",\"detail\":\"Gives IID the power to shut large-load users off first when energy demand soars during peak periods (KPBS).\",\"source_url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\"},{\"term\":\"Service-ability determination\",\"detail\":\"Establishes a formal process for determining whether IID can reliably serve a proposed large load and what system improvements may be required (APPA).\"}],\"legislation\":[],\"source_url\":\"https://kesq.com/news/2026/09/15/iid-board-unanimously-approves-large-load-tariff/\",\"source_title\":\"KESQ — IID board unanimously approves large load tariff\",\"resources\":[{\"url\":\"https://www.publicpower.org/periodical/article/imperial-irrigation-district-board-unanimously-approves-large-load-tariff\",\"title\":\"American Public Power Association — Imperial Irrigation District Board Unanimously Approves Large Load Tariff\"},{\"url\":\"https://www.kpbs.org/news/environment/2026/09/16/imperial-valley-utility-adopts-new-pricing-rules-putting-data-centers-first-for-power-cuts\",\"title\":\"KPBS — Imperial Valley utility adopts new pricing rules, putting data centers first for power cuts\"}],\"related\":[],\"captured_at\":\"2026-11-16\"},{\"id\":\"pacificorp-oregon-schedule-401-ue463\",\"utility\":\"Pacific Power (PacifiCorp)\",\"state\":\"OR\",\"jurisdiction_level\":\"state\",\"tariff_name\":\"Schedule 401 — Service to New Large Energy Use Facilities (Advice No. 25-015)\",\"tariff_type\":\"Data center / large energy use facility rate class (HB 3546 POWER Act implementation)\",\"status\":\"approved\",\"status_detail\":\"Docket UE 463 shows status SUSPENDED (under Commission investigation); Order No. 26-310 (Aug. 31, 2026) suspended the tariff sheets' effective date until December 31, 2026. Filed October 2, 2025 as ADV 1790, which the Commission closed December 16, 2025 with all filings moved to UE 463 after AWEC, Amazon and the Data Center Coalition intervened. On September 16, 2026 PacifiCorp filed a motion to admit an executed stipulation among PUC Staff, PacifiCorp, the Citizens' Utility Board and Environmental Intervenors, with joint supporting testimony from Robert Meredith, Bret Stevens, Ryan Tran and Jeremy Fisher. As of September 25, 2026 the docket's own filing log shows no Commission order acting on the stipulation yet; the December 31, 2026 suspension deadline is the next dated step. Docket log through October 20, 2026: on October 1 the Data Center Coalition filed a notice of opposition to the stipulation; on October 16 the Stipulating Parties filed a joint brief; on October 19 an ALJ ruling set the deadline for motions to admit testimony and witness declarations; PacifiCorp (October 19) and AWEC (October 20) filed such motions. No order on the stipulation had issued. On November 13, 2026 the Commission entered Order No. 26-443 (disposition: stipulation adopted), finding that the stipulation is in the public interest and will result in just and reasonable rates; the docket lists an effective date of January 1, 2027.\",\"regulator\":\"Public Utility Commission of Oregon (OPUC)\",\"docket_number\":\"UE 463 (originally ADV 1790 / Advice No. 25-015)\",\"filed_date\":\"2025-10-02\",\"decision_date\":\"2026-11-13\",\"min_load_mw\":20.0,\"summary\":\"PacifiCorp's proposed Schedule 401 implements Oregon HB 3546 (the POWER Act) by creating a separate customer class for new Large Energy Use Facilities — facilities that 'use or are able to use 20 megawatts (MW) or more' and are primarily engaged in NAICS 518210 data processing and hosting — and requiring each to sign a Commission-approved service agreement of not less than 10 years with minimum-payment provisions, so that the significant investments needed to serve loads ranging 'from 20 MW to potentially 1 gigawatt or more' are not shifted to residential and other customers. A stipulation resolving the case was filed September 16, 2026 and awaits Commission action. The OPUC adopted the stipulation resolving the case in Order No. 26-443 on November 13, 2026; the order describes a direct contracting and direct assignment approach plus a 1-cent per kilowatt-hour surcharge on large data centers.\",\"parameters\":{\"min_demand_threshold\":{\"status\":\"included\",\"detail\":\"Schedule 401 applies to Large Energy Use Facilities: data processing facilities using or able to use 20 MW or more.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"a facility that uses or is able to use 20 megawatts or more and is primarily engaged in providing a service described under the 2022 North American Industry Classification System Code 518210\"},\"customer_type\":{\"status\":\"included\",\"detail\":\"Schedule 401 is limited to facilities in NAICS 518210 (data processing, hosting and related services), per Oregon HB 3546.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"“Computing Infrastructure Providers, Data Processing, Web Hosting, and Related Services.”\"},\"aggregation_rules\":{\"status\":\"included\",\"detail\":\"Sites with common ownership within 2,500 feet or on the same substation count as one; data center customers with similar ownership statewide have contract demand summed.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"If two or more sites have common ownership and are within 2,500 feet of each other or are served by the same substation, the sites will be treated as one\"},\"min_contract_duration\":{\"status\":\"included\",\"detail\":\"Minimum 10-year LEUF agreement term, up to 30 years including ramp; renewals at least 10 years.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"sets a minimum 10-year LEUF Agreement term, with a maximum term of 30 years, inclusive of any ramp period\"},\"load_ramp_period\":{\"status\":\"partial\",\"detail\":\"Ramp period is counted inside the 10 to 30 year term; no maximum ramp length set.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"sets a minimum 10-year LEUF Agreement term, with a maximum term of 30 years, inclusive of any ramp period\"},\"monthly_demand_charge\":{\"status\":\"included\",\"detail\":\"Peak Demand Charge on the month's highest demand equal to the sum of OATT Schedule 1, Schedule 3 and network integration transmission service rates.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"will subject the New LEUF to a Peak Demand Charge that is based on the customer's highest demand during the month\"},\"collateral\":{\"status\":\"included\",\"detail\":\"Customer must show A-/A3-level creditworthiness or post collateral covering its Exit Fee, reassessed every two years.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"a LEUF shall, at the company's election, be required to provide sufficient creditworthiness or post collateral to cover the customer's Exit Fee\"},\"direct_cost_assignment\":{\"status\":\"included\",\"detail\":\"Direct contracting and direct assignment approach: network upgrades paid upfront, generation and storage costs recovered by reservation charge or customer resources.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"adopting a direct contracting and direct assignment approach\"},\"dca_interconnection\":{\"status\":\"included\",\"detail\":\"Line extensions follow Rule 13; Network Upgrades needed to serve the facility are paid upfront by the customer.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"any Network Upgrades (as defined in Rule 13, including bulk transmission) required to serve the New LEUF's load will be paid for upfront by the New LEUF\"},\"dca_network_transmission\":{\"status\":\"included\",\"detail\":\"Upfront payment of network upgrades, except qualified 230 kV+ WECC critical-path upgrades where the customer pays its usage share via monthly fee.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"unless following criteria are all met: i. The Network Upgrade is a transmission facility of 230 kV and above\"},\"dca_generation_capacity\":{\"status\":\"included\",\"detail\":\"Customer pays full cost of generation and storage resources via a monthly Reservation Charge on Contract Demand, or reimburses its own Customer Resources plus risk and firming charges.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"will require the New LEUF to compensate PacifiCorp for the full cost of all necessary generation and storage resources in one of two ways\"},\"customer_resource_procurement\":{\"status\":\"included\",\"detail\":\"Option where the customer dictates the resources used to serve it ('Customer Resources').\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"where the LEUF dictates the resources to be used to serve it (Customer Resources)\"},\"customer_led_procurement\":{\"status\":\"included\",\"detail\":\"Customer Resources are reimbursed at actual cost plus a Portfolio Risk Management Charge and a System Firming and Balancing Charge (33% of system fixed generation).\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"a System Firming and Balancing Charge set at 33 percent of System Fixed Generation applicable to Schedule 48\"},\"load_flexibility\":{\"status\":\"partial\",\"detail\":\"Agreements may account for interruptible service; PacifiCorp must propose a flexibility compensation program in its next general rate case.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"PacifiCorp will propose a uniform flexibility compensation program based on avoided cost principles for New LEUF customers\"},\"price_premium\":{\"status\":\"included\",\"detail\":\"Community Energy Benefits Charge of 1 cent per kWh on facilities over 100 MW, funding energy efficiency, home repairs or DER for low-income customers (reverts to 0 if the PGE charge is struck down).\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"imposes a 1 cent/kW charge on LEUFs over 100 MW to fund non-cost-effective energy efficiency, critical home repairs\"},\"study_requirements\":{\"status\":\"included\",\"detail\":\"$25,000 non-refundable application fee; engineering studies funded by and allocated fully to the customer; study cost true-up.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"imposes a $25,000 nonrefundable application fee as an offset to the costs of PacifiCorp's preparing the LEUF Agreement\"},\"hold_harmless\":{\"status\":\"included\",\"detail\":\"Schedule must mitigate unwarranted cost shifting; each agreement must not harm resource adequacy or HB 2021 compliance for existing customers.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"Each LEUF Agreement will ensure that the New LEUF's load is served in a manner that does not harm PacifiCorp's resource adequacy position\"},\"no_harm_analysis\":{\"status\":\"included\",\"detail\":\"PacifiCorp must analyze the generation and capacity resources needed to serve each new LEUF without impeding HB 2021 compliance, filed with each agreement approval.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"requires that each standard LEUF Agreement and Schedule 401 require PacifiCorp to analyze the generation and capacity resources necessary to serve the New LEUF's load\"},\"exit_fee\":{\"status\":\"included\",\"detail\":\"Exit fee covers net book value of company-funded infrastructure, customer-specific power agreements, remaining Reservation Charge and removal costs.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"The Exit Fee will include the net book value of company-funded infrastructure\"},\"resize_reassign\":{\"status\":\"included\",\"detail\":\"Exit fee is refunded pro rata if another large customer takes the capacity within three years.\",\"source_url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"verbatim\":\"If another large customer takes service within three years of an exiting LEUF's departure, the Exit Fee will be refunded by a pro-rata share of the capacity assumed by the new large customer.\"}},\"additional_terms\":[{\"term\":\"Existing facilities deferred\",\"detail\":\"PacifiCorp plans to address HB 3546 implementation for existing Large Energy Use Facilities in its next general rate case.\"}],\"legislation\":[{\"policy_id\":\"or-hb3546-2025\",\"title\":\"Oregon HB 3546 (2025) — large energy use facilities\",\"url\":\"https://olis.oregonlegislature.gov/liz/2025R1/Measures/Overview/HB3546\",\"citation\":\"HB 3546, Chapter 323 (2025)\",\"status\":\"Enacted 2025 (effective June 16, 2025)\",\"summary\":\"Requires the Oregon PUC to create a separate service classification for large energy use facilities (20 MW+) that assigns serving costs to them — the POWER Act, which Schedule 401 implements for PacifiCorp.\"}],\"source_url\":\"https://apps.puc.state.or.us/edockets/DocketNoLayout.asp?DocketID=24856\",\"source_title\":\"Oregon PUC eDockets — UE 463, PacifiCorp Advice No. 25-015 Schedule 401 (docket sheet)\",\"resources\":[{\"url\":\"https://edocs.puc.state.or.us/efdocs/UAA/uaa340367027.pdf\",\"title\":\"PacifiCorp — Advice No. 25-015, Schedule 401 Service to New Large Energy Use Facilities (filing letter and tariff sheets, October 2, 2025)\"},{\"url\":\"https://apps.puc.state.or.us/edockets/docket.asp?DocketID=24769\",\"title\":\"Oregon PUC eDockets — ADV 1790 (closed; filings moved to UE 463)\"},{\"url\":\"https://www.oregon.gov/puc/news-events/Documents/PR-202609.pdf\",\"title\":\"Oregon PUC media release (UM 2377) — Oregon PUC Approves New Rate Structure to Protect Customers Amid Rapid Data Center Growth (notes UE 463 is under consideration)\"},{\"url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"title\":\"OPUC — Order No. 26-443 (UE 463), Nov. 13, 2026\"}],\"related\":[],\"captured_at\":\"2026-11-16\"}],\"brief\":{\"as_of\":\"2026-11-16\",\"paragraphs\":[{\"heading\":\"Decisions due next\",\"text\":\"Arizona's administrative law judge is expected to recommend an order in the APS rate case by late November, and the Corporation Commission must vote by December 31. Duke's North Carolina large-load settlement, filed October 6 with Amazon, Google and Microsoft among the signers, asks for rates to start January 1, 2027. Colorado's PUC has held Xcel's large-load tariff until January 8, 2027 while it hears the case. Pennsylvania's PUC holds a technical conference on how to split large-load costs on November 17.\",\"record_refs\":[{\"kind\":\"rate_case\",\"id\":\"az-acc-aps-rate-case-2025\",\"relation\":\"related\",\"note\":\"APS rate case\"},{\"kind\":\"tariff\",\"id\":\"duke-nc-large-load-rate-case-2025\",\"relation\":\"related\",\"note\":\"Duke NC large-load tariff\"},{\"kind\":\"tariff\",\"id\":\"xcel-colorado-large-load-tariff\",\"relation\":\"related\",\"note\":\"Xcel Colorado tariff\"},{\"kind\":\"rate_case\",\"id\":\"pa-puc-large-load-cost-allocation-2026\",\"relation\":\"related\",\"note\":\"PA cost-allocation proceeding\"}],\"sources\":[{\"url\":\"https://azcc.gov/news/home/2026/02/19/what-s-next-in-the-aps-rate-case\",\"title\":\"Arizona Corporation Commission — What's next in the APS rate case\"},{\"url\":\"https://www.selc.org/wp-content/uploads/2026/10/2026-10-06-Duke-Energy-LLT-Settlement.pdf\",\"title\":\"Duke Energy large load tariff settlement, Oct 6, 2026 (NCUC filing)\"},{\"url\":\"https://www.dora.state.co.us/pls/efi/EFI.Show_Docket?p_session_id=&p_docket_id=26AL-0137E\",\"title\":\"Colorado PUC — Proceeding 26AL-0137E\"},{\"url\":\"https://www.puc.pa.gov/press-release/2026/puc-moves-to-address-data-center-impacts-on-electric-reliability-and-consumer-costs-09102026\",\"title\":\"Pennsylvania PUC — large-load cost allocation proceeding\"}]},{\"heading\":\"Regulators pushing back\",\"text\":\"Florida's Public Service Commission denied Duke Energy Florida's large-load tariffs on November 3, finding the proposal left out customers the new state law covers and did not show those customers would pay their full cost of service. In Wisconsin, Oracle is suing the PSC over the credit-rating requirement in We Energies' Very Large Customer tariff, and the PSC has declined to loosen it.\",\"record_refs\":[{\"kind\":\"rate_case\",\"id\":\"fl-psc-duke-large-load-tariff-2026\",\"relation\":\"related\",\"note\":\"Duke Florida case\"},{\"kind\":\"tariff\",\"id\":\"we-energies-very-large-customer-tariff\",\"relation\":\"related\",\"note\":\"We Energies tariff\"}],\"sources\":[{\"url\":\"https://www.wusf.org/politics-issues/2026-11-04/regulators-reject-dukes-data-center-rate-structure\",\"title\":\"WUSF — Regulators reject Duke's data center rate structure\"},{\"url\":\"https://wisconsinwatch.org/2026/07/wisconsin-regulators-refuse-to-loosen-data-center-credit-rules-setting-up-oracle-court-fight/\",\"title\":\"Wisconsin Watch — Regulators refuse to loosen data center credit rules\"}]},{\"heading\":\"Laws setting the terms\",\"text\":\"New Jersey's Data Center Fair Share Act, signed July 7, has the Board of Public Utilities create a separate rate class for large data centers; the board sets standards first, then utilities file tariffs. Oregon's POWER Act (HB 3546) has now produced two approved tariffs: Portland General Electric's Schedule 96 in May and PacifiCorp's Schedule 401 on November 13.\",\"record_refs\":[{\"kind\":\"policy\",\"id\":\"nj-pl2026-c32\",\"relation\":\"related\",\"note\":\"NJ Fair Share Act\"},{\"kind\":\"policy\",\"id\":\"or-hb3546-2025\",\"relation\":\"related\",\"note\":\"Oregon HB 3546\"},{\"kind\":\"tariff\",\"id\":\"pge-oregon-schedule-96-large-load\",\"relation\":\"related\",\"note\":\"PGE Schedule 96\"},{\"kind\":\"tariff\",\"id\":\"pacificorp-oregon-schedule-401-ue463\",\"relation\":\"related\",\"note\":\"PacifiCorp Schedule 401\"}],\"sources\":[{\"url\":\"https://www.nj.gov/governor/news/2026/20260707a.shtml\",\"title\":\"Office of the Governor of New Jersey — July 7, 2026\"},{\"url\":\"https://apps.puc.state.or.us/orders/2026ords/26-154.pdf\",\"title\":\"Oregon PUC Order No. 26-154 (PGE Schedule 96)\"},{\"url\":\"https://apps.puc.state.or.us/orders/2026ords/26-443.pdf\",\"title\":\"Oregon PUC Order No. 26-443 (PacifiCorp Schedule 401)\"}]},{\"heading\":\"What new tariffs have in common\",\"text\":\"Berkeley Lab's August 2026 review of 55 large-load tariffs found a minimum demand threshold in nearly all of them, with a median of 25 MW, and a minimum contract term in nearly all of them too. The elements it calls emerging, meaning they appear more often in tariffs proposed since January 2025, are study requirements, load ramp periods, hold-harmless provisions, rules for resizing contracted capacity, and exit fees.\",\"record_refs\":[],\"sources\":[{\"url\":\"https://eta-publications.lbl.gov/sites/default/files/2026-08/rate_designs_large_loads_2026.08.10.pdf\",\"title\":\"Berkeley Lab — Electricity Rate Designs for Large Loads, 2026 Update\"}]}]}}";
